window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II e frasi con wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Se fossi in te, …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La realtà di Eva – i desideri di Eva. Completa con: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Però le piacerebbe essere più alta.","why":"*grösser sein*: la forma del desiderio di *sein* è **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Però le piacerebbe parlare bene lo spagnolo.","why":"Alla fine c'è un infinito (*sprechen*), quindi il desiderio è **würde** + infinito.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Però preferirebbe lavorare come guida turistica.","why":"Infinito alla fine (*arbeiten*) → **würde** + infinito. *lieber* = piuttosto, preferibilmente.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Però le piacerebbe avere un appartamento grande.","why":"*eine Wohnung haben*: la forma del desiderio di *haben* è **hätte**. Non serve un infinito.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"Che cosa pensano le persone?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Abbina ogni immagine a un'espressione del riquadro.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Se non dovessi lavorare, adesso sarei seduto in giardino.","why":"L'immagine 1 lo mostra mentre lavora, poi mentre sogna su una sdraio. Dopo una frase con *wenn* la principale comincia con il verbo (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Se avessi una macchina, non dovrei andare in bici sotto la pioggia.","why":"Va in bici sotto la pioggia; una macchina gli risparmierebbe questo. *müsste* è il Konjunktiv II di *müssen*. *Velo* è la parola svizzera per *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Se il bus non fosse in ritardo, sarei puntuale in ufficio.","why":"Un bus in ritardo la fa arrivare tardi al lavoro. *wäre* è il Konjunktiv II di *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Riscrivi le frasi di a: comincia con la principale, poi la frase con wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Non dovrei andare in bici sotto la pioggia, se avessi una macchina.","why":"Prima la principale, poi la frase con *wenn*. Nella frase con *wenn* il verbo (*hätte*) va alla fine.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Sarei puntuale in ufficio, se il bus non fosse in ritardo.","why":"Stesso schema: principale, virgola, *wenn* … verbo alla fine (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Completa con le parole del riquadro. Ogni parola si usa una volta; quelle barrate sono usate nell'esempio.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Farei alcune cose in modo diverso, se fossi a capo della nostra ditta.","why":"*machen* alla fine → **würde** + infinito. *Chefin sein* → **wäre**, alla fine della frase con *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Se fossi Marco, farei assolutamente una formazione professionale.","why":"*Marco sein* → **wäre** (come *Wenn ich du wäre …*). La principale ha l'infinito *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Se potessi decidere liberamente, lavorerei in una piccola ditta.","why":"*frei entscheiden können* → **könnte** alla fine della frase con *wenn*. Principale con *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Se avessimo dei figli, dovrei lavorare solo a metà tempo.","why":"*Kinder haben* con *wir* → **hätten**. Il riquadro lascia **müsste** per l'ultimo spazio.","source":"k2","check":"*müsste* e *würde* sono entrambi tedesco corretto in b, c ed e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* va altrettanto bene). Il riquadro dice solo che tre spazi prendono *würde* e uno prende *müsste*; questa soluzione è la ripartizione più probabile. Chiedi al tuo insegnante quale vuole il libro."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Devo sbrigarmi a causa del mio lavoro.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Riscrivi le risposte con weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Perché la mia ragazza non è puntuale.","why":"*wegen* + sostantivo diventa *weil* + una frase con un verbo; il verbo (*ist*) va alla fine.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Perché il tempo è brutto.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; dopo *weil* il verbo va alla fine.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Perché ho un appuntamento importante.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusativo dopo *haben*); verbo alla fine.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Completa con: wegen – weshalb – weil – deswegen – denn. Una parola può essere usata più volte.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"A causa della sua pronuncia lo capisco solo male.","why":"Segue un sostantivo (*seiner Aussprache*, genitivo), non una frase → la preposizione **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Un giorno vorrei viaggiare in Italia, perché vorrei vedere il mare.","why":"Dopo lo spazio il verbo resta in 2a posizione (*ich möchte*) → **denn**. Con *weil* andrebbe alla fine.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Devo migliorare la comprensione orale, per questo guardo molti film.","why":"La seconda parte è la conseguenza, e il verbo viene subito dopo lo spazio (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"I miei figli hanno imparato il tedesco in fretta, perché all'asilo stanno sempre con bambini svizzeri.","why":"Il verbo è alla fine (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Perché scrivi le parole su dei bigliettini?","why":"Serve una parola interrogativa: **Weshalb** significa *warum* (perché)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Mia sorella parla già il tedesco quasi correntemente, per questo può aiutarmi a impararlo.","why":"Conseguenza, e il verbo viene subito dopo lo spazio (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Al corso di lingua. Completa con: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Non sono riuscito a fare l'ultimo esercizio, perché non l'avevo capito.","why":"Il verbo è alla fine (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"All'iscrizione non c'era nessuno. Per questo sono tornato a casa.","why":"Una nuova frase che dà la conseguenza, con il verbo subito dopo lo spazio (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Grazie ai miei bei voti non ho dovuto fare un test all'inizio del corso.","why":"Segue un gruppo nominale (*meiner guten Noten*, genitivo plurale) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"C'è un corso di lingua in più, perché si sono iscritti moltissimi partecipanti.","why":"Il verbo è alla fine (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Ieri purtroppo non sono potuto venire al corso a causa del mal di denti.","why":"Segue un gruppo nominale (*meiner Zahnschmerzen*, genitivo plurale) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Chi trova le scuse migliori? Scegli una situazione e scrivi. Le risposte modello sono solo una possibilità ciascuna.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Purtroppo non ho potuto riordinare la cucina, perché all'improvviso ho avuto un forte mal di schiena. Ho dovuto sdraiarmi. Per questo ho guardato un film.","why":"Usa *weil* (verbo alla fine: *hatte*) e *Deswegen* (verbo subito dopo: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"A causa dell'influenza non sono andato all'esame finale. Avevo la febbre alta, per questo sono rimasto a letto.","why":"Usa *wegen* + genitivo (*einer Grippe*) e *deswegen* + verbo (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Mi dispiace tanto! Purtroppo sono arrivato tardi, perché in autostrada c'era stato un incidente. A causa della coda ho perso due ore.","why":"*denn* lascia il verbo in 2a posizione (*war*). *wegen des Staus*: genitivo di *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (frasi ipotetiche, comprese quelle irreali con il Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"dizionario dei connettivi di grammis: wenn (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"dizionario dei connettivi di grammis: weil (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"dizionario dei connettivi di grammis: denn (causale, il verbo resta in 2a posizione)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"dizionario dei connettivi di grammis: deswegen (conseguenza; sta prima del verbo o in mezzo alla frase)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con il genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}]},{"id":"02-mehrere-sprachen","no":2,"title":"In mehreren Sprachen zu Hause","title_en":"Crescere con più lingue · lettura, post nel forum, cruciverba, parole preferite","added":"2026-11-09","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 135","heading":"E  In mehreren Sprachen zu Hause","heading_en":"A casa in più lingue","exercises":[{"no":"17","tag":"E2","instruction":"Zwei oder drei Sprachen in einer Familie – kein Problem?","instruction_en":"Due o tre lingue in una famiglia – nessun problema?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ergänzen Sie die Namen.","part_instruction_en":"Chi dice cosa? Leggi i tre testi e scrivi il nome della persona che dice ciascuna frase.","reading":[{"label":"A · Amira, 33","text":"Ich denke, das ist manchmal schwierig, aber es geht. Bei uns ist das so: Ich bin Ägypterin und mein Deutsch ist noch nicht so gut, weil ich erst seit zwei Jahren in der Schweiz lebe. Mein Mann ist Schweizer. Wir haben uns in Ägypten kennengelernt, weil er dort sechs Jahre für eine Schweizer Firma gearbeitet hat. Jetzt leben wir seit fast zwei Jahren in Basel. Unsere Kinder sprechen sehr gut Arabisch und jetzt auch schon ziemlich gut Schweizerdeutsch. Mein Mann hat zwar in Ägypten mit ihnen Schweizerdeutsch gesprochen, aber er war ja nicht so viel zu Hause und in der Familie haben wir immer Arabisch gesprochen. Darum können das die Kinder viel besser. Manchmal verwenden sie auch zwei Sprachen in einem Satz. Wenn sie ein Wort nicht auf Schweizerdeutsch wissen, dann sagen sie einfach ein arabisches mitten im deutschen Satz. Aber ich finde das okay. Bald kommen sie in die Schule und dann werden sie sowieso besser Schweizerdeutsch als Arabisch sprechen."},{"label":"B · Janusz, 22","text":"Ich bin Pole, und als ich sechs Jahre alt war, sind wir in die Schweiz umgezogen. Meine Schwester und ich sind natürlich gleich in eine öffentliche Schule gegangen und konnten nach einem Jahr fliessend Hochdeutsch sprechen. Für meine Eltern war es schwieriger, denn meine Mutter war Hausfrau und hatte nicht so viel Kontakt zu Schweizern. Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet. Wir wollten nicht, dass unsere Eltern oder unsere Grossmutter mit uns Polnisch sprechen, wenn andere Kinder zu Besuch waren oder sie uns von der Schule abgeholt haben. Ich glaube, alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen. Natürlich ist mein Polnisch nicht so gut wie mein Deutsch, aber ich verstehe alles und kann auch ziemlich gut Alltagsgespräche führen. Das ist genug für mich und ich freue mich, dass ich mich mit unseren polnischen Verwandten unterhalten kann. Ich finde, man sollte daraus nicht so ein Problem machen."},{"label":"C · Yara, 18","text":"Ich komme aus Syrien. Ich bin mit drei Sprachen aufgewachsen, denn mein Vater hat für eine internationale Firma gearbeitet und wir haben auch einige Jahre in der Türkei und in Russland gelebt. Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch. Allerdings kann ich Arabisch am besten, weil wir in der Familie immer Arabisch gesprochen haben, egal in welchem Land wir waren. Jetzt leben wir in in der Schweiz und ich lerne seit zwei Jahren Deutsch. Das kann ich noch nicht so gut. Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf. Ich möchte Übersetzerin werden und so muss ich die Sprachen nicht mehr lernen. Das ist doch super, oder?"}],"items":[{"label":"1","text":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: ___","gaps":[["Janusz"]],"solution":"«Kinder wollen dieselbe Sprache sprechen wie ihre Freunde.» Name: **Janusz**","en":"“I bambini vogliono parlare la stessa lingua dei loro amici.” – Janusz","why":"Janusz (testo B): *alle Kinder wollen sein wie die anderen Kinder und dazu gehört auch, dieselbe Sprache zu sprechen.*"},{"label":"2","text":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: ___","gaps":[["Yara"]],"solution":"«Es ist doch gut, wenn man mehrere Sprachen sehr gut spricht.» Name: **Yara**","en":"“È bello parlare molto bene più lingue, no?” – Yara","why":"Yara (testo C): *Ich persönlich finde es sehr gut, dass ich mit drei Sprachen aufgewachsen bin, denn ich habe viele Vorteile im Beruf.*"},{"label":"3","text":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: ___","gaps":[["Amira"]],"solution":"«Meine Kinder wechseln zwischen zwei Sprachen.» Name: **Amira**","en":"“I miei figli passano da una lingua all'altra.” – Amira","why":"Amira (testo A): *Manchmal verwenden sie auch zwei Sprachen in einem Satz.* È l'unica che parla dei propri figli."}]},{"no":"17","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Che cosa è giusto? Rileggi i testi. Scrivi *richtig* (giusto) o *falsch* (sbagliato) dopo ogni frase; nel libro segni solo quelle giuste.","items":[{"label":"1","text":"Amiras Kinder sprechen besser Arabisch als Deutsch. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Amiras Kinder sprechen besser Arabisch als Deutsch. → **richtig**","en":"I figli di Amira parlano l'arabo meglio del tedesco. → giusto","why":"In famiglia si parla sempre arabo: *Darum können das die Kinder viel besser.* (Il loro tedesco qui è lo svizzero tedesco.)"},{"label":"2","text":"In Amiras Familie wird nur Deutsch gesprochen. → ___","gaps":[["falsch","f","nein"]],"solution":"In Amiras Familie wird nur Deutsch gesprochen. → **falsch**","en":"Nella famiglia di Amira si parla solo tedesco. → sbagliato","why":"Il contrario: *in der Familie haben wir immer Arabisch gesprochen.*"},{"label":"3","text":"Janusz hat sechs Jahre Deutsch gelernt. → ___","gaps":[["falsch","f","nein"]],"solution":"Janusz hat sechs Jahre Deutsch gelernt. → **falsch**","en":"Janusz ha imparato il tedesco per sei anni. → sbagliato","why":"Aveva sei anni quando la famiglia si è trasferita (*als ich sechs Jahre alt war*) e dopo un anno parlava correntemente l'alto tedesco."},{"label":"4","text":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Janusz und seine Schwester wollten mit ihren Eltern nicht Polnisch sprechen. → **richtig**","en":"Janusz e sua sorella non volevano parlare polacco con i genitori. → giusto","why":"*Nach zwei Jahren wollten meine Schwester und ich nur noch Deutsch sprechen und wir haben unseren Eltern immer auf Deutsch geantwortet.*"},{"label":"5","text":"Yara spricht drei Sprachen fliessend. → ___","gaps":[["richtig","r","ja","x"]],"solution":"Yara spricht drei Sprachen fliessend. → **richtig**","en":"Yara parla tre lingue correntemente. → giusto","why":"*Aus diesem Grund spreche ich sehr gut Arabisch, Türkisch und Russisch.* Il tedesco è la sua quarta lingua e non lo parla ancora bene."},{"label":"6","text":"Yara lernt jetzt bald auch Deutsch. → ___","gaps":[["falsch","f","nein"]],"solution":"Yara lernt jetzt bald auch Deutsch. → **falsch**","en":"Yara presto imparerà anche il tedesco. → sbagliato","why":"Non comincia presto (*bald*): impara già il tedesco da due anni (*ich lerne seit zwei Jahren Deutsch*)."}]}]},{"page":"AB 136","heading":"E  In mehreren Sprachen zu Hause","heading_en":"A casa in più lingue","exercises":[{"no":"18","tag":"E2 · Prüfung","instruction":"Einen Forumsbeitrag schreiben. Sie haben im Fernsehen eine Diskussionssendung zum Thema «Mehrsprachig aufwachsen» gesehen. Im Online-Forum der Sendung finden Sie folgende Meinung:","instruction_en":"Scrivere un post nel forum. Hai guardato un dibattito in TV sul crescere con più lingue. Nel forum online della trasmissione trovi questa opinione:","reading":[{"label":"Online-Forum · 15.01. 16.55 Uhr · Sandra (52 Jahre)","text":"Also, ich kann den Gästen in Ihrer Sendung überhaupt nicht zustimmen. Ich finde, dass Kinder zuerst einmal eine Sprache richtig lernen sollen. Denn sonst können sie am Ende gar keine Sprache gut. Sie sprechen dann zwar zwei oder drei Sprachen ein bisschen, mischen sie aber und sprechen keine Sprache fliessend und auch keine wirklich gut."}],"part":"a","part_instruction":"Machen Sie Notizen.","part_instruction_en":"Prendi appunti sulle quattro domande. Bastano appunti brevi, niente frasi complete. Gli appunti del modello sono una possibilità.","items":[{"label":"1","lead":"Kennen Sie eine Person, die mit zwei Sprachen aufwächst/aufgewachsen ist?","text":"","open":true,"solution":"Ja: der Sohn von meiner Nachbarin – Italienisch mit der Mutter, Schweizerdeutsch in der Schule","en":"Sì: il figlio della mia vicina – italiano con la madre, svizzero tedesco a scuola","why":"Solo appunti: un nome o una persona e quali lingue dove."},{"label":"2","lead":"Was finden Sie gut?","text":"","open":true,"solution":"zwei Sprachen ohne Kurs lernen, Kontakt mit der Familie im Ausland, Vorteile im Beruf","en":"imparare due lingue senza un corso, contatto con la famiglia all'estero, vantaggi nel lavoro","why":"Raccogli due o tre vantaggi; ti servono per *Ich finde es sehr gut, dass …* in b."},{"label":"3","lead":"Was könnte schwierig sein?","text":"","open":true,"solution":"die Sprachen mischen, eine Sprache ist schwächer, viel Arbeit für die Eltern","en":"mescolare le lingue, una lingua è più debole, molto lavoro per i genitori","why":"Questi vanno in *Es könnte schwierig sein, dass …* e *Auf der anderen Seite …* in b."},{"label":"4","lead":"Stimmen Sie Sandra zu?","text":"","open":true,"solution":"nein – Kinder lernen zwei Sprachen gut, wenn die Eltern viel mit ihnen sprechen","en":"no – i bambini imparano bene due lingue se i genitori parlano molto con loro","why":"Decidi sì o no e dai un motivo: diventa *Ich stimme Sandra (nicht) zu, denn …*."}]},{"no":"18","part":"b","part_instruction":"Schreiben Sie nun Ihre Meinung zum Thema (circa 80 Wörter).","part_instruction_en":"Ora scrivi la tua opinione sul tema (circa 80 parole). Usa i tuoi appunti di a e alcune delle espressioni.","phrases":["Ich denke, dass …","Ich finde es sehr gut/wichtig, dass …","Am allerwichtigsten ist … Deswegen/Daher/Aus diesem Grund …","Es könnte schwierig sein, dass …","Auf der anderen Seite …","Ich stimme Sandra (nicht) zu, denn …","**LERNTIPP** Sie brauchen diese Sätze, wenn Sie Ihre Meinung ausdrücken wollen. Wiederholen Sie sie möglichst oft."],"items":[{"label":"b","text":"","open":true,"solution":"Ich stimme Sandra nicht zu, **denn** viele Kinder lernen zwei Sprachen ohne Probleme. Der Sohn von meiner Nachbarin wächst mit Italienisch und Deutsch auf. Mit seiner Mutter spricht er Italienisch, in der Schule Schweizerdeutsch. Ich finde es sehr gut, dass er so früh zwei Sprachen lernt. Es könnte schwierig sein, dass er die Sprachen manchmal mischt. Auf der anderen Seite ist das bei kleinen Kindern normal. Am allerwichtigsten ist, dass die Eltern viel mit dem Kind sprechen. **Deswegen** sollte jeder Elternteil seine eigene Sprache sprechen.","en":"Non sono d'accordo con Sandra, perché molti bambini imparano due lingue senza problemi. Il figlio della mia vicina cresce con l'italiano e il tedesco. Con sua madre parla italiano, a scuola svizzero tedesco. Trovo molto bello che impari due lingue così presto. Potrebbe essere difficile che a volte mescoli le lingue. D'altra parte, per i bambini piccoli è normale. La cosa più importante di tutte è che i genitori parlino molto con il bambino. Per questo ogni genitore dovrebbe parlare la propria lingua.","why":"Circa 85 parole, con sei delle espressioni. *denn* lascia il verbo al secondo posto (*lernen*); dopo *Deswegen* viene subito il verbo (*sollte*).","source":"deswegen"}]},{"no":"19","tag":"E3","instruction":"Lösen Sie das Rätsel.","instruction_en":"Risolvi il cruciverba. Ogni frase indica la prima lettera della parola mancante. La griglia non è mostrata qui: scrivi la parola intera. Nella griglia del libro la Ä occupa una sola casella.","items":[{"label":"a","lead":"Unser Heimatland ist Spanien. Wir s… aus Spanien.","text":"___","gaps":[["stammen"]],"solution":"**stammen**","en":"Il nostro paese d'origine è la Spagna. Veniamo dalla Spagna.","why":"*aus einem Land stammen* = provenire da un paese (come *kommen aus*)."},{"label":"b","lead":"Jolanda und Mike sehen sich sechs Monate nicht. Das ist eine lange T… .","text":"___","gaps":[["Trennung"]],"solution":"**Trennung**","en":"Jolanda e Mike non si vedono per sei mesi. È una lunga separazione.","why":"*die Trennung* = separazione, il sostantivo di *sich trennen*. *eine lange* → un sostantivo femminile."},{"label":"c","lead":"Deutsch und Arabisch haben nicht die gleiche S… .","text":"___","gaps":[["Schrift"]],"solution":"**Schrift**","en":"Il tedesco e l'arabo non hanno la stessa scrittura.","why":"*die Schrift* = scrittura, le lettere con cui si scrive una lingua. L'arabo usa un altro alfabeto."},{"label":"d","lead":"Peter lebt jetzt in Amerika. Seit er dort lebt, hat er sich stark v… .","text":"___","gaps":[["verändert"]],"solution":"**verändert**","en":"Peter ora vive in America. Da quando vive lì, è cambiato molto.","why":"*sich verändern* = cambiare (come persona). Perfekt: *hat sich verändert*. La Ä occupa una sola casella."},{"label":"e","lead":"Sie schreibt Bücher. Sie ist A… von Beruf.","text":"___","gaps":[["Autorin"]],"solution":"**Autorin**","en":"Scrive libri. Di professione è un'autrice.","why":"*Sie* → la forma femminile con *-in*: *der Autor → die Autorin*. Nessun articolo dopo *sein … von Beruf*."},{"label":"f","lead":"Die Kinder machen ihre Hausaufgaben nicht. Deshalb s… die Eltern mit ihnen.","text":"___","gaps":[["schimpfen"]],"solution":"**schimpfen**","en":"I bambini non fanno i compiti. Per questo i genitori li sgridano.","why":"*mit jemandem schimpfen* = sgridare qualcuno. Soggetto plurale *die Eltern* → *schimpfen*. Dopo *Deshalb* viene subito il verbo."},{"label":"g","lead":"Sie arbeitet erst seit wenigen Monaten. Sie hat noch wenig E… in ihrem Beruf.","text":"___","gaps":[["Erfahrung"]],"solution":"**Erfahrung**","en":"Lavora solo da pochi mesi. Ha ancora poca esperienza nel suo lavoro.","why":"*die Erfahrung* = esperienza. *wenig Erfahrung haben* = avere poca esperienza."},{"label":"h","lead":"Jetzt haben wir ein Chaos. Alles ist d… .","text":"___","gaps":[["durcheinander"]],"solution":"**durcheinander**","en":"Ora abbiamo il caos. È tutto in disordine.","why":"*durcheinander sein* = essere in disordine, confuso. Si scrive in una parola."},{"label":"i","lead":"Für Ye-Jon tönen die Laute P und F gleich. Sie kann sie nicht u… .","text":"___","gaps":[["unterscheiden"]],"solution":"**unterscheiden**","en":"Per Ye-Jon i suoni P e F suonano uguali. Non riesce a distinguerli.","why":"*unterscheiden* = distinguere. Con *kann* l'infinito va in fondo. *tönen* è svizzero per *klingen* (suonare)."},{"label":"j","lead":"Ich reise in den Ferien nach Griechenland, aber leider kann ich kein G… .","text":"___","gaps":[["Griechisch"]],"solution":"**Griechisch**","en":"In vacanza vado in Grecia, ma purtroppo non so parlare il greco.","why":"*Griechisch* = la lingua greca, con la maiuscola. *kein Griechisch können* = non saper parlare il greco."},{"label":"k","lead":"Er isst nur Gemüse und Reis. Er isst a… Gemüse und Reis.","text":"___","gaps":[["ausschliesslich"]],"solution":"**ausschliesslich**","en":"Mangia solo verdura e riso. Mangia esclusivamente verdura e riso.","why":"*ausschliesslich* = esclusivamente, nient'altro che. Grafia svizzera con *ss*; in Germania si scrive con la s scharf (Eszett)."},{"label":"★","lead":"Lösungswort (die markierte Zeile im Rätsel)","text":"___","gaps":[["Muttersprache"]],"solution":"**Muttersprache**","en":"Parola risolutiva (la riga evidenziata nella griglia): lingua madre","why":"Ogni parola dà una lettera della riga evidenziata: stam**M**en, trenn**U**ng, schrif**T**, (T nella griglia), veränd**E**rt, auto**R**in, (S nella griglia), schim**P**fen, erfah**R**ung, durchein**A**nder, unters**C**heiden, griec**H**isch, ausschli**E**sslich."}]}]},{"page":"AB 137","heading":"E  In mehreren Sprachen zu Hause","heading_en":"A casa in più lingue","exercises":[{"no":"20","tag":"E3","instruction":"Mein schönstes deutsches Wort","instruction_en":"La mia parola tedesca più bella","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Abbina ogni foto a una parola del riquadro. I pallini colorati del libro indicano l'articolo: blu = der, verde = das, rosso = die.","box":["Sommervogel","Caramelchöpfli","Sternschnuppe"],"box_exact":true,"items":[{"label":"1","lead":"(Foto 1: ein Dessert mit Karamellsauce auf einem Teller)","text":"___","gaps":[["Caramelchöpfli","das Caramelchöpfli"]],"solution":"**Caramelchöpfli**","en":"das Caramelchöpfli – crème caramel (un dolce al cucchiaio al caramello)","why":"Nome svizzero della crème caramel. *Chöpfli* in svizzero tedesco significa “testolina” (*Kopf*). Pallino verde → *das*."},{"label":"2","lead":"(Foto 2: ein Stern mit einem langen, hellen Schweif am Nachthimmel)","text":"___","gaps":[["Sternschnuppe","die Sternschnuppe"]],"solution":"**Sternschnuppe**","en":"die Sternschnuppe – stella cadente","why":"*der Stern* = stella; *die Sternschnuppe* = stella cadente. Pallino rosso → *die*."},{"label":"3","lead":"(Foto 3: ein blauer Schmetterling auf einer orangen Blume)","text":"___","gaps":[["Sommervogel","der Sommervogel"]],"solution":"**Sommervogel**","en":"der Sommervogel – farfalla","why":"Parola svizzera per *der Schmetterling* (farfalla); il Duden la segna come *schweizerisch, sonst landschaftlich*. Pallino blu → *der*.","source":"sommervogel"}]},{"no":"20","part":"b","part_instruction":"Warum findet wohl jemand genau diese Wörter am schönsten? Was meinen Sie? Machen Sie Notizen und sprechen Sie.","part_instruction_en":"Perché qualcuno potrebbe trovare proprio queste parole le più belle? Tu che cosa ne pensi? Prendi appunti, poi parlatene. Gli appunti del modello sono una possibilità.","example":[{"text":"Sommervogel: so farbig, …"}],"items":[{"label":"1","lead":"Sommervogel","text":"","open":true,"solution":"so farbig und leicht, erinnert an den Sommer, lustig: das Tier ist ja kein Vogel","en":"così colorata e leggera, ricorda l'estate, buffo: l'animale non è affatto un uccello","why":"Pensa a che cosa ti fa vedere o sentire la parola e a come suona."},{"label":"2","lead":"Caramelchöpfli","text":"","open":true,"solution":"süss, erinnert an die Kindheit, tönt lustig und typisch schweizerisch","en":"dolce, ricorda l'infanzia, suona buffa e tipicamente svizzera","why":"*tönen* = svizzero per *klingen* (suonare)."},{"label":"3","lead":"Sternschnuppe","text":"","open":true,"solution":"romantisch, man kann sich etwas wünschen, tönt weich","en":"romantica, si può esprimere un desiderio, suona morbida","why":"Bastano appunti brevi: aggettivi e un motivo."}]},{"no":"21","tag":"E3","instruction":"Mein Lieblingswort","instruction_en":"La mia parola preferita","part":"a","part_instruction":"Welches deutsche Wort und welches Wort in Ihrer Muttersprache gefallen Ihnen? Warum? Schreiben Sie.","part_instruction_en":"Quale parola tedesca e quale parola della tua lingua madre ti piacciono? Perché? Scrivi un breve testo usando le espressioni. La risposta modello è una possibilità.","phrases":["Wenn ich … höre, dann denke ich an …","Deshalb finde ich …","Dieses Wort ist …","Das tönt …","Für mich ist …","Auf Deutsch/In meiner Muttersprache …"],"example":[{"text":"Wenn ich das Wort «Sommervogel» höre, dann denke ich an …"}],"items":[{"label":"a","text":"","open":true,"solution":"Mein deutsches Lieblingswort ist «gemütlich». **Wenn** ich dieses Wort höre, **dann** denke ich an einen Winterabend mit Tee, Kerzen und Freunden. **Deshalb** finde ich es so schön. Das tönt weich und warm. In meiner Muttersprache Englisch gibt es kein Wort mit genau dieser Bedeutung. Auf Englisch gefällt mir das Wort «sunshine». Für mich ist es ein fröhliches Wort, denn es tönt hell und freundlich.","en":"La mia parola tedesca preferita è “gemütlich” (accogliente). Quando sento questa parola, penso a una sera d'inverno con tè, candele e amici. Per questo la trovo così bella. Suona morbida e calda. Nella mia lingua madre, l'Inglese, non c'è una parola con esattamente questo significato. In inglese mi piace la parola “sunshine”. Per me è una parola allegra, perché suona luminosa e amichevole.","why":"*Wenn …, dann* + verbo subito dopo (*denke ich*); *Deshalb* + verbo subito dopo (*finde ich*). Sostituisci con la tua lingua madre e le tue parole.","source":"wenn"}]},{"no":"21","part":"b","part_instruction":"Präsentieren Sie Ihren Text im Kurs.","part_instruction_en":"Presenta il tuo testo in classe. Nel modello trovi un possibile inizio.","items":[{"label":"b","text":"","open":true,"solution":"Ich möchte euch heute mein Lieblingswort vorstellen. Es ist das Wort «gemütlich». …","en":"Oggi vorrei presentarvi la mia parola preferita. È la parola “gemütlich”. …","why":"Comincia nominando la parola, poi leggi il tuo testo di a. *euch* per i compagni di classe, *Ihnen* se parli in modo formale."}]}]}],"sources":[{"id":"sommervogel","title":"Duden: Sommervogel (schweizerisch, sonst landschaftlich = Schmetterling)","url":"https://www.duden.de/rechtschreibung/Sommervogel"},{"id":"deswegen","title":"grammis, dizionario dei connettori: deswegen (conseguenza; sta prima del verbo o in mezzo)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wenn","title":"grammis, dizionario dei connettori: wenn (subordinante, verbo in fondo)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"}]},{"id":"03-nachfragen-test","no":3,"title":"Nachfragen · Fremdsprachen lernen · Test Lektion 4","title_en":"Chiedere spiegazioni con cortesia, imparare le lingue, cercare lavoro · Test della lezione 4","added":"2026-11-10","book":"Schritte plus Neu 5 · Arbeitsbuch und Testheft · Lektion 4","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (soluzioni ufficiali, Lektion 4)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (frasi ipotetiche, comprese quelle irreali con il Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"weil","title":"dizionario dei connettivi di grammis: weil (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"dizionario dei connettivi di grammis: denn (causale, il verbo resta in 2a posizione)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"dizionario dei connettivi di grammis: deswegen (conseguenza; sta prima del verbo o in mezzo alla frase)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"deshalb","title":"dizionario dei connettivi di grammis: deshalb (conseguenza; sinonimi daher, deswegen)","url":"https://grammis.ids-mannheim.de/konnektoren/407094"},{"id":"darum","title":"dizionario dei connettivi di grammis: d(a)rum (conseguenza)","url":"https://grammis.ids-mannheim.de/konnektoren/407096"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con il genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}],"pages":[{"page":"AB 133","heading":"C  Entschuldigung, könnten Sie das bitte wiederholen?","heading_en":"Scusi, potrebbe ripeterlo, per favore?","exercises":[{"no":"13","tag":"C2","instruction":"Ordnen Sie zu.","instruction_en":"Completa ogni domanda o frase con un inizio del riquadro. Ogni inizio si usa una volta; quello barrato è usato nell'esempio.","box":["Tut mir leid, das Wort habe ich","Könnten Sie bitte langsamer","Entschuldigung, habe ich das","Könnten Sie das bitte","Darf ich Sie schnell","Was bedeutet","Könnten Sie mir vielleicht sagen","Wissen Sie, ob"],"box_used":[4],"box_exact":true,"example":[{"label":"a","text":"**Darf ich Sie schnell** etwas fragen?"}],"items":[{"label":"b","text":"___ der Ausdruck «es eilig haben»?","gaps":[["Was bedeutet"]],"solution":"**Was bedeutet** der Ausdruck «es eilig haben»?","en":"Che cosa significa l'espressione “es eilig haben”?","why":"*Was bedeutet …?* chiede il significato di una parola o di un'espressione. (*es eilig haben* = avere fretta.)","source":"hueber"},{"label":"c","text":"___ sprechen?","gaps":[["Könnten Sie bitte langsamer"]],"solution":"**Könnten Sie bitte langsamer** sprechen?","en":"Potrebbe parlare più lentamente, per favore?","why":"*Könnten Sie …* (Konjunktiv II) rende la richiesta cortese; l'infinito *sprechen* va alla fine.","source":"hueber"},{"label":"d","text":"___ nicht verstanden.","gaps":[["Tut mir leid, das Wort habe ich"]],"solution":"**Tut mir leid, das Wort habe ich** nicht verstanden.","en":"Mi dispiace, quella parola non l'ho capita.","why":"Perfekt: *habe … verstanden*; *das Wort* sta al primo posto per dare enfasi, quindi il verbo *habe* viene subito dopo.","source":"hueber"},{"label":"e","text":"Wie bitte? ___ wiederholen?","gaps":[["Könnten Sie das bitte"]],"solution":"Wie bitte? **Könnten Sie das bitte** wiederholen?","en":"Come, scusi? Potrebbe ripeterlo, per favore?","why":"Una richiesta cortese con *Könnten Sie …*; *wiederholen* (ripetere) va alla fine.","source":"hueber"},{"label":"f","text":"___ es hier auch Integrationskurse gibt?","gaps":[["Wissen Sie, ob"]],"solution":"**Wissen Sie, ob** es hier auch Integrationskurse gibt?","en":"Sa se qui ci sono anche dei corsi d'integrazione?","why":"*ob* introduce una domanda indiretta sì/no, quindi il verbo *gibt* va alla fine.","source":"hueber"},{"label":"g","text":"___ richtig verstanden?","gaps":[["Entschuldigung, habe ich das"]],"solution":"**Entschuldigung, habe ich das** richtig verstanden?","en":"Scusi, ho capito bene?","why":"Una domanda sì/no al Perfekt: prima *habe*, *verstanden* alla fine.","source":"hueber"},{"label":"h","text":"___, wo die Mensa ist?","gaps":[["Könnten Sie mir vielleicht sagen"]],"solution":"**Könnten Sie mir vielleicht sagen**, wo die Mensa ist?","en":"Potrebbe dirmi per caso dov'è la mensa?","why":"Una domanda indiretta con *wo*: il verbo *ist* va alla fine. *die Mensa* = la mensa universitaria.","source":"hueber"}]},{"no":"14","tag":"C2","instruction":"Ergänzen Sie.","instruction_en":"Completa i dialoghi. Le iniziali stampate (e alcune lettere all'interno delle parole) sono date; scrivi le parole mancanti per intero.","example":[{"label":"a","lead":"◆ Was ist denn das? ○ Das ist ein Zigerkrapfen. ◆ Entschuldigung, Zigerkrapfen kenne ich nicht.","text":"**Könnten Sie mir sagen**, was das ist?"}],"items":[{"label":"b","lead":"◆ Entschuldigen Sie bitte. Wo ist denn da die Mensa?  ○ Wie bitte? Das letzte Wort h… i… n… v… .  ◆ Die Mensa, die Uni-Kantine.","text":"Wie bitte? Das letzte Wort ___.","gaps":[["habe ich nicht verstanden"]],"solution":"Wie bitte? Das letzte Wort **habe ich nicht verstanden**.","en":"Come, scusi? L'ultima parola non l'ho capita.","why":"Perfekt: *habe* in 2a posizione dopo *Das letzte Wort*, *verstanden* alla fine.","source":"hueber"},{"label":"c","lead":"◆ Also, dann treffen wir uns am 12.5. um 13.35 Uhr am Bahnhof.  ○ Entschuldigen Sie, es ist so laut da. K… S… den Termin b… w…?","text":"Entschuldigen Sie, es ist so laut da. ___ den Termin ___ ___?","gaps":[["Könnten Sie"],["bitte"],["wiederholen"]],"solution":"Entschuldigen Sie, es ist so laut da. **Könnten Sie** den Termin **bitte wiederholen**?","en":"Mi scusi, qui c'è così tanto rumore. Potrebbe ripetere l'orario, per favore?","why":"Richiesta cortese: *Könnten Sie* … infinito *wiederholen* alla fine. *der Termin* qui = l'orario dell'appuntamento.","source":"hueber"},{"label":"d","lead":"◆ D… i… S… etwas f…?  ○ Ja, gern.  ◆ W… S…, o… es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","text":"◆ ___ etwas ___? ○ Ja, gern. ◆ ___, ___ es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","gaps":[["Darf ich Sie"],["fragen"],["Wissen Sie"],["ob"]],"solution":"◆ **Darf ich Sie** etwas **fragen**? ○ Ja, gern. ◆ **Wissen Sie**, **ob** es in dem Zug um 14.33 Uhr nach Genf auch ein Bistro oder Restaurant gibt?","en":"Posso chiederle una cosa? – Sì, certo. – Sa se sul treno delle 14.33 per Ginevra c'è anche un bistrot o un ristorante?","why":"*Darf ich Sie etwas fragen?* apre in modo cortese; *ob* introduce una domanda indiretta sì/no, quindi *gibt* va alla fine.","source":"hueber"}]},{"no":"15","tag":"C2","instruction":"Bilden Sie Wörter und ordnen Sie zu.","instruction_en":"Forma delle parole con le sillabe del riquadro e completa le frasi. Le sillabe barrate (Men, sa) sono usate nell'esempio.","phrases":["schrei · druck · ni · lung · ker · der · auf · Aus · ben · ho · Me · Wie · cha  (durchgestrichen im Beispiel: Men, sa)"],"example":[{"label":"a","text":"Ich wähle in der **Mensa** immer ein vegetarisches Gericht."}],"items":[{"label":"b","text":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten ___ geben? Diesmal will ich sie mir gleich in meinem Adressbuch ___, damit ich sie nicht wieder verliere.","gaps":[["Mechaniker"],["aufschreiben"]],"solution":"Mein Auto ist schon wieder kaputt. Könntest du mir bitte noch einmal die Telefonnummer von deinem guten **Mechaniker** geben? Diesmal will ich sie mir gleich in meinem Adressbuch **aufschreiben**, damit ich sie nicht wieder verliere.","en":"La mia macchina è di nuovo rotta. Potresti darmi ancora una volta il numero di telefono del tuo bravo meccanico, per favore? Questa volta voglio scrivermelo subito nella rubrica, così non lo perdo di nuovo.","why":"Me-cha-ni-ker (una persona che ripara le automobili) e auf-schrei-ben (infinito alla fine dopo *will*).","source":"hueber"},{"label":"c","text":"Was bedeutet der ___ «eine Entscheidung treffen»? Den habe ich noch nie gehört.","gaps":[["Ausdruck"]],"solution":"Was bedeutet der **Ausdruck** «eine Entscheidung treffen»? Den habe ich noch nie gehört.","en":"Che cosa significa l'espressione “eine Entscheidung treffen”? Non l'ho mai sentita.","why":"Aus-druck: *der Ausdruck* = espressione; *der* e *Den* mostrano che è maschile. (*eine Entscheidung treffen* = prendere una decisione.)","source":"hueber"},{"label":"d","text":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur ___.","gaps":[["Wiederholung"]],"solution":"Leider vergesse ich oft wichtige deutsche Wörter. Ich brauche mehr Zeit zur **Wiederholung**.","en":"Purtroppo dimentico spesso parole tedesche importanti. Ho bisogno di più tempo per il ripasso.","why":"Wie-der-ho-lung: *zur* = *zu der*, quindi segue un sostantivo femminile: *die Wiederholung* (ripasso, ripetizione).","source":"hueber"}]}]},{"page":"AB 134","heading":"D  Fremdsprachen lernen – aber wie?","heading_en":"Imparare le lingue straniere – ma come?","exercises":[{"no":"16","tag":"D1","instruction":"Fremdsprachen lernen – aber wie?","instruction_en":"Imparare le lingue straniere – ma come?","part":"a","part_instruction":"Wer sagt was? Lesen Sie und ordnen Sie zu.","part_instruction_en":"Chi dice cosa? Leggi i tre testi e scrivi dopo ogni frase la lettera del testo (A, B o C).","reading":[{"label":"A  Mila, 17 Jahre","text":"Ich finde es total wichtig, dass man neue Wörter lernt und sie immer wieder wiederholt. Ich schreibe sie auf kleine Zettel oder Karten, auf der einen Seite das fremdsprachige Wort und auf der anderen die Übersetzung in meine Muttersprache. Diese Wortkarten habe ich immer in meiner Handtasche. Jeden Tag fahre ich eine Stunde mit dem Zug zur Schule. Das ist langweilig. Da habe ich viel Zeit und dann hole ich meine Wortkarten heraus und wiederhole die Wörter."},{"label":"B  Hakan, 19 Jahre","text":"Ich lerne seit vier Jahren Englisch in der Schule. Mir hilft es sehr, wenn ich viel Englisch höre. Ich habe viele MP3s mit Übungen aus dem Englischbuch und für die Aussprache auf meinem Smartphone. Ausserdem habe ich im Internet gute englische Podcasts gefunden. Die höre ich, wenn ich unterwegs bin. Ich möchte irgendwann nach der Schule ein Jahr nach London gehen und mir dort einen Job suchen. Darum will ich gut Englisch sprechen und auch meine Aussprache verbessern."},{"label":"C  Danila, 16 Jahre","text":"Ich bin vor drei Jahren in die Schweiz gekommen. Jetzt kann ich schon ziemlich gut Deutsch. Viel Zuhören ist für mich am allerwichtigsten. Deswegen habe ich im Bus, auf der Strasse, einfach überall immer den Schweizern zugehört und viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien. So habe ich viele Wörter und kleine Sätze der Alltagssprache gelernt, sogar auf Dialekt. Immer nur Grammatik und Wörter lernen, das finde ich uninteressant."}],"example":[{"label":"1","text":"Ich möchte meine Aussprache verbessern. → **B**"}],"items":[{"label":"2","text":"Ich höre oft anderen Leuten zu. → ___","gaps":[["C","Danila"]],"solution":"Ich höre oft anderen Leuten zu. → **C**","en":"Ascolto spesso le altre persone. → C (Danila)","why":"Danila: *Deswegen habe ich … einfach überall immer den Schweizern zugehört.*","source":"hueber"},{"label":"3","text":"Auf dem Weg zur Schule lerne ich Wörter. → ___","gaps":[["A","Mila"]],"solution":"Auf dem Weg zur Schule lerne ich Wörter. → **A**","en":"Mentre vado a scuola imparo le parole. → A (Mila)","why":"Mila tira fuori i suoi bigliettini durante l'ora di treno per andare a scuola.","source":"hueber"},{"label":"4","text":"Ich möchte nach der Schule in England arbeiten. → ___","gaps":[["B","Hakan"]],"solution":"Ich möchte nach der Schule in England arbeiten. → **B**","en":"Dopo la scuola vorrei lavorare in Inghilterra. → B (Hakan)","why":"Hakan: *… ein Jahr nach London gehen und mir dort einen Job suchen.*","source":"hueber"},{"label":"5","text":"Ich schaue viel deutschsprachiges Fernsehen. → ___","gaps":[["C","Danila"]],"solution":"Ich schaue viel deutschsprachiges Fernsehen. → **C**","en":"Guardo molta televisione in lingua tedesca. → C (Danila)","why":"Danila: *… viel deutschsprachiges Fernsehen geschaut. Einfache Filme oder Serien.*","source":"hueber"},{"label":"6","text":"Ich schreibe Wortkarten. → ___","gaps":[["A","Mila"]],"solution":"Ich schreibe Wortkarten. → **A**","en":"Scrivo bigliettini con le parole. → A (Mila)","why":"Mila scrive la parola straniera su un lato del bigliettino e la traduzione sull'altro.","source":"hueber"}]},{"no":"16","part":"b","part_instruction":"Schreiben Sie Sätze.","part_instruction_en":"Scrivi la seconda frase: comincia con la parola data (Deshalb, Darum …) e usa le parole tra parentesi. Il verbo viene subito dopo la parola iniziale.","example":[{"label":"1","lead":"Mila möchte viele neue Wörter lernen. (neue Wörter auf Wortkarten schreiben)","text":"Deshalb **schreibt sie neue Wörter auf Wortkarten**."}],"items":[{"label":"2","lead":"Mila findet den Weg zur Schule langweilig. (mit Wortkarten neue Wörter wiederholen)","text":"","accept":["Darum wiederholt sie neue Wörter mit Wortkarten.","Darum wiederholt sie mit Wortkarten neue Wörter."],"solution":"**Darum wiederholt sie neue Wörter mit Wortkarten.**","en":"Per questo ripassa le parole nuove con i bigliettini.","why":"*Darum* occupa la 1a posizione, quindi segue il verbo coniugato *wiederholt*, poi il soggetto *sie*.","source":"darum"},{"label":"3","lead":"Hakan hilft es, wenn er viel Englisch hört. (viele Podcasts auf seinem Smartphone haben)","text":"","accept":["Aus diesem Grund hat er viele Podcasts auf seinem Smartphone."],"solution":"**Aus diesem Grund hat er viele Podcasts auf seinem Smartphone.**","en":"Per questo motivo ha molti podcast sul suo smartphone.","why":"*Aus diesem Grund* occupa la 1a posizione come *deshalb*: subito dopo il verbo *hat*, poi *er*.","source":"hueber"},{"label":"4","lead":"Hakan möchte nach der Schule ein Jahr in London arbeiten. (gut Englisch sprechen wollen)","text":"","accept":["Deswegen will er gut Englisch sprechen."],"solution":"**Deswegen will er gut Englisch sprechen.**","en":"Per questo vuole parlare bene l'inglese.","why":"*Deswegen* + verbo modale *will* in 2a posizione, infinito *sprechen* alla fine.","source":"deswegen"},{"label":"5","lead":"Danila findet Grammatik und Wörter lernen uninteressant. (viel deutschsprachiges Fernsehen schauen)","text":"","accept":["Daher schaut sie viel deutschsprachiges Fernsehen."],"solution":"**Daher schaut sie viel deutschsprachiges Fernsehen.**","en":"Perciò guarda molta televisione in lingua tedesca.","why":"*Daher* significa lo stesso di *deshalb*; il verbo *schaut* viene subito dopo.","source":"deshalb"},{"label":"6","lead":"Für Danila ist Zuhören am allerwichtigsten. (einfach überall immer den Schweizern zugehört)","text":"","accept":["Aus diesem Grund hört sie einfach überall immer den Schweizern zu.","Aus diesem Grund hat sie einfach überall immer den Schweizern zugehört."],"solution":"**Aus diesem Grund hört sie einfach überall immer den Schweizern zu.**","en":"Per questo motivo ascolta semplicemente gli svizzeri, sempre e ovunque.","why":"*zuhören* è separabile: *hört … zu*. Il testo stampa *zugehört*, quindi è corretto anche il Perfekt *hat … zugehört* (come nel testo di Danila).","source":"hueber","check":"La soluzione ufficiale dà il presente (*hört … zu*), anche se il testo stampa il participio *zugehört*. Entrambe le frasi sono tedesco corretto; chiedi al tuo insegnante quale vuole il libro."}]}]},{"page":"AB 138","heading":"Test Lektion 4","heading_en":"Test della lezione 4","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Completa il testo di Arif. Il libro dà la prima lettera e alcune lettere all'interno di ogni parola; scrivi la parola intera.","reading":[{"text":"Ich heisse Arif und bin 16 Jahre alt. Meine Familie und ich stammen (a) aus Syrien und unsere M… (b) ist Arabisch. Jetzt lerne ich seit einem Jahr Deutsch. Nächstes Jahr möchte ich eine Lehre beginnen. D… (c) möchte ich mein Deutsch verbessern. Natürlich spreche ich dann noch nicht f… (d) Deutsch. Besonders die Schrift und die A… (e) finde ich schwierig und ich verstehe auch noch nicht alle A… (f). Aber ich bin optimistisch."}],"example":[{"label":"a","text":"Meine Familie und ich **stammen** aus Syrien."}],"items":[{"label":"b","lead":"… und unsere M _ t _ _ _ s _ _ _ c _ _ ist Arabisch.","text":"… und unsere ___ ist Arabisch.","gaps":[["Muttersprache"]],"solution":"… und unsere **Muttersprache** ist Arabisch.","en":"… e la nostra lingua madre è l'arabo.","why":"*die Muttersprache* = la prima lingua con cui cresci."},{"label":"c","lead":"D _ _ _ e _ e _ möchte ich mein Deutsch verbessern.","text":"___ möchte ich mein Deutsch verbessern.","gaps":[["Deswegen"]],"solution":"**Deswegen** möchte ich mein Deutsch verbessern.","en":"Per questo vorrei migliorare il mio tedesco.","why":"Lo schema delle lettere (D, e, e) corrisponde a *Deswegen*; esprime la conseguenza, e il verbo *möchte* viene subito dopo.","source":"deswegen"},{"label":"d","lead":"Natürlich spreche ich dann noch nicht f _ _ _ _ _ e _ _ Deutsch.","text":"Natürlich spreche ich dann noch nicht ___ Deutsch.","gaps":[["fliessend"]],"solution":"Natürlich spreche ich dann noch nicht **fliessend** Deutsch.","en":"Naturalmente allora non parlerò ancora il tedesco correntemente.","why":"*fliessend* = correntemente, fluente. Ortografia svizzera con *ss*."},{"label":"e","lead":"Besonders die Schrift und die A _ _ _ p _ _ _ _ e finde ich schwierig …","text":"Besonders die Schrift und die ___ finde ich schwierig …","gaps":[["Aussprache"]],"solution":"Besonders die Schrift und die **Aussprache** finde ich schwierig …","en":"Trovo difficili soprattutto la scrittura e la pronuncia …","why":"*die Aussprache* = pronuncia (*aussprechen* = pronunciare)."},{"label":"f","lead":"… und ich verstehe auch noch nicht alle A _ _ d _ _ c _ e.","text":"… und ich verstehe auch noch nicht alle ___.","gaps":[["Ausdrücke"]],"solution":"… und ich verstehe auch noch nicht alle **Ausdrücke**.","en":"… e non capisco ancora nemmeno tutte le espressioni.","why":"*der Ausdruck, die Ausdrücke* = espressione/espressioni; *alle* richiede il plurale."}]},{"no":"2","instruction":"Schreiben Sie Sätze mit wenn.","instruction_en":"Scrivi frasi ipotetiche irreali con *wenn* e il Konjunktiv II (*wäre, hätte, könnte, müsste* o *würde* + infinito).","example":[{"label":"a","lead":"(ich heute nicht so viel vorhaben – spazieren gehen)","text":"Wenn **ich heute nicht so viel vorhätte, würde ich spazieren gehen**."}],"items":[{"label":"b","lead":"(ich mein Englisch besser sein – dir bei der Hausaufgabe helfen können)","text":"","accept":["Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.","Wenn mein Englisch besser wäre, würde ich dir bei der Hausaufgabe helfen können."],"solution":"**Wenn mein Englisch besser wäre, könnte ich dir bei der Hausaufgabe helfen.**","en":"Se il mio inglese fosse migliore, potrei aiutarti con i compiti.","why":"*sein* → **wäre** alla fine della frase con *wenn*; *können* → **könnte**, poi la principale comincia con il verbo.","source":"kond"},{"label":"c","lead":"(ich euch besser verstehen – ihr nicht durcheinander sprechen)","text":"","accept":["Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.","Ich würde euch besser verstehen, wenn ihr nicht durcheinandersprechen würdet.","Ich könnte euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet."],"solution":"**Ich würde euch besser verstehen, wenn ihr nicht durcheinander sprechen würdet.**","en":"Vi capirei meglio se non parlaste tutti insieme.","why":"Prima la principale; *würde* + infinito in entrambe le parti. Nella frase con *wenn* *würdet* va alla fine.","source":"kond"},{"label":"d","lead":"(ich mehr Freizeit haben – nicht so viel arbeiten müssen)","text":"","accept":["Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste."],"solution":"**Ich hätte mehr Freizeit, wenn ich nicht so viel arbeiten müsste.**","en":"Avrei più tempo libero se non dovessi lavorare così tanto.","why":"*haben* → **hätte**, *müssen* → **müsste** (alla fine della frase con *wenn*).","source":"k2"}]},{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Completa con una parola del riquadro. Ogni parola si usa una volta; quella barrata è usata nell'esempio (la soluzione della frase a).","box":["denn","Weshalb","Weil","Wegen","Deswegen"],"box_used":[2],"box_exact":true,"items":[{"label":"a","text":"___ möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","gaps":[["Weshalb"]],"solution":"**Weshalb** möchte Costa Mechatroniker werden? – Weil er sich für Autos interessiert.","en":"Perché Costa vuole diventare meccatronico? – Perché si interessa di automobili.","why":"Serve una parola interrogativa; **Weshalb** = *warum* (perché). La risposta stampata comincia con *Weil*.","source":"weil"},{"label":"b","text":"___ seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","gaps":[["Wegen"]],"solution":"**Wegen** seiner guten Deutschkenntnisse hat er schnell eine Lehrstelle gefunden.","en":"Grazie alle sue buone conoscenze di tedesco ha trovato in fretta un posto di apprendistato.","why":"Segue un gruppo nominale (*seiner guten Deutschkenntnisse*, genitivo plurale) → la preposizione **Wegen**.","source":"wegen"},{"label":"c","text":"Er ist erst 17 Jahre alt. ___ wohnt er noch bei seinen Eltern.","gaps":[["Deswegen"]],"solution":"Er ist erst 17 Jahre alt. **Deswegen** wohnt er noch bei seinen Eltern.","en":"Ha solo 17 anni. Per questo abita ancora dai suoi genitori.","why":"Una conseguenza, e il verbo viene subito dopo lo spazio (*wohnt er*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Jetzt spart er Geld, ___ er möchte nach der Ausbildung eine eigene Wohnung haben.","gaps":[["denn"]],"solution":"Jetzt spart er Geld, **denn** er möchte nach der Ausbildung eine eigene Wohnung haben.","en":"Adesso risparmia, perché dopo la formazione vorrebbe avere un appartamento suo.","why":"Una causa, e il verbo resta in 2a posizione (*er möchte*) → **denn**.","source":"denn"}]},{"no":"4","instruction":"Wie kann man auch sagen? Ergänzen Sie.","instruction_en":"In quale altro modo puoi dirlo? Completa la seconda espressione. Il libro dà alcune lettere; scrivi le parole intere.","example":[{"label":"a","text":"Können Sie mir sagen, wo …? – **Wissen Sie**, wo …?"}],"items":[{"label":"b","lead":"Ich habe eine Frage. – D _ _ _  i _ _  S _ _  e _ _ _ _  f _ _ _ _ _?","text":"Ich habe eine Frage. – ___?","gaps":[["Darf ich Sie etwas fragen"]],"solution":"Ich habe eine Frage. – **Darf ich Sie etwas fragen**?","en":"Ho una domanda. – Posso chiederle una cosa?","why":"Un modo cortese per introdurre una domanda: *Darf ich Sie etwas fragen?*"},{"label":"c","lead":"Könnten Sie das bitte noch einmal sagen? – K _ _ _ t _ _  S _ _  d _ s  b _ _ t _  wi _ _ _ h _ _ _ _?","text":"Könnten Sie das bitte noch einmal sagen? – ___?","gaps":[["Könnten Sie das bitte wiederholen"]],"solution":"Könnten Sie das bitte noch einmal sagen? – **Könnten Sie das bitte wiederholen**?","en":"Potrebbe dirlo ancora una volta, per favore? – Potrebbe ripeterlo, per favore?","why":"*wiederholen* = ripetere = *noch einmal sagen*."},{"label":"d","lead":"Was meinen Sie mit …? – W _ _  b _ _ e _ _ _ _ …?","text":"Was meinen Sie mit …? – ___ …?","gaps":[["Was bedeutet"]],"solution":"Was meinen Sie mit …? – **Was bedeutet** …?","en":"Che cosa intende con …? – Che cosa significa …?","why":"*Was bedeutet …?* chiede il significato, come *Was meinen Sie mit …?*","check":"Nella foto le lettere di questo spazio si leggono male; *Was bedeutet …?* corrisponde a quelle lettere ed è l'espressione dell'esercizio 13. Chiedi al tuo insegnante se il tuo libro mostra altro."},{"label":"e","lead":"Entschuldigung. – T _ _  m _ _  l _ _ _.","text":"Entschuldigung. – ___.","gaps":[["Tut mir leid"]],"solution":"Entschuldigung. – **Tut mir leid**.","en":"Scusi. – Mi dispiace.","why":"*Tut mir leid* = mi dispiace, un altro modo per scusarsi."}]}]},{"page":"AB 139","heading":"Fokus Beruf: Stellensuche","heading_en":"Focus lavoro: cercare un impiego","exercises":[{"no":"1","instruction":"Yusuf sucht eine neue Stelle als Coiffeur. Er liest eine Broschüre mit Tipps für die Stellensuche. Lesen Sie die Tipps und ordnen Sie die Überschriften zu.","instruction_en":"Yusuf cerca un nuovo lavoro come parrucchiere. Legge un opuscolo con consigli per la ricerca di lavoro. Leggi i consigli e scrivi dopo ogni paragrafo la lettera del titolo giusto (A–E).","reading":[{"label":"1","text":"Machen Sie eine Liste von Personen, die Sie persönlich kennen: Bekannte, Kollegen, Freunde und Verwandte. Notieren Sie auch die Namen von früheren Arbeitgebern und Arbeitskollegen. Informieren Sie diese Personen – mündlich oder schriftlich – darüber, dass Sie auf Stellensuche sind. Wichtig: Informieren Sie Ihre Kontaktpersonen, wenn Sie eine Stelle gefunden haben."},{"label":"2","text":"Werden Sie aktiv. Warten Sie nicht, bis Sie ein passendes Stelleninserat finden, sondern schreiben Sie Ihre eigene Stellenanzeige. Suchen Sie ein Internet-Portal, das zu Ihrer Branche passt, und präsentieren Sie sich. Solche Annoncen kosten viel weniger als gedruckte Annoncen und Sie können sie ausserdem noch mit einer eigenen Bewerber-Website verbinden."},{"label":"3","text":"Erhöhen Sie Ihre Erfolgschancen mit einer Kurzbewerbung. Suchen Sie sich Ihre Wunschfirma und bewerben Sie sich. Dafür braucht es natürlich eine gute Recherche, damit Sie die «richtige» Firma und die «richtige» Person anschreiben. Wie ihr Name sagt, ist diese Bewerbung kurz: Sie besteht aus einem Bewerbungsschreiben und dem tabellarischen Lebenslauf."},{"label":"4","text":"Sind in Ihrer Branche Bewerbungen per Telefon üblich? Sind Sie besonders mutig und überzeugen vor allem mündlich sehr gut? Aus welchem Grund Sie sich für diese Bewerbungsform entscheiden: Wichtig ist auch hier eine gründliche Vorbereitung. Machen Sie Notizen und üben Sie das Gespräch mit Freunden. Fehlt Ihnen der Mut dazu, wählen Sie die schriftliche Bewerbung."},{"label":"5","text":"Die grösste Auswahl an Stelleninseraten finden Sie im Internet. Wichtig ist eine sorgfältige Analyse der Inserate: Was will die Firma? Welche Qualifikationen und Erfahrungen haben Sie? Machen Sie eine Liste und beantworten Sie diese Fragen. Können Sie ca. 80 Prozent der Anforderungen erfüllen, dann ist eine Bewerbung sinnvoll."}],"items":[{"label":"1","text":"Absatz 1 (Liste von Personen, die Sie kennen) → ___","gaps":[["C","C Das persönliche Netzwerk"]],"solution":"Absatz 1 (Liste von Personen, die Sie kennen) → **C**","en":"Paragrafo 1 (un elenco di persone che conosci) → C, La tua rete personale","why":"Amici, colleghi ed ex datori di lavoro sono la tua rete personale.","source":"hueber"},{"label":"2","text":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → ___","gaps":[["A","A Online-Stellengesuch"]],"solution":"Absatz 2 (Ihre eigene Stellenanzeige im Internet) → **A**","en":"Paragrafo 2 (il tuo annuncio di ricerca di lavoro su internet) → A, Annuncio di ricerca di lavoro online","why":"*das Stellengesuch* = un annuncio in cui cerchi lavoro; qui su un portale internet.","source":"hueber"},{"label":"3","text":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → ___","gaps":[["E","E Spontanbewerbung"]],"solution":"Absatz 3 (Kurzbewerbung bei Ihrer Wunschfirma) → **E**","en":"Paragrafo 3 (una breve candidatura presso l'azienda dei tuoi sogni) → E, Candidatura spontanea","why":"Ti candidi presso un'azienda che non ha pubblicato nessuna offerta di lavoro: *die Spontanbewerbung*.","source":"hueber"},{"label":"4","text":"Absatz 4 (Bewerbungen per Telefon) → ___","gaps":[["D","D Telefonische Bewerbung"]],"solution":"Absatz 4 (Bewerbungen per Telefon) → **D**","en":"Paragrafo 4 (candidarsi per telefono) → D, Candidatura telefonica","why":"*per Telefon* = *telefonisch*.","source":"hueber"},{"label":"5","text":"Absatz 5 (Stelleninserate im Internet analysieren) → ___","gaps":[["B","B Stelleninserate"]],"solution":"Absatz 5 (Stelleninserate im Internet analysieren) → **B**","en":"Paragrafo 5 (analizzare gli annunci di lavoro su internet) → B, Annunci di lavoro","why":"*das Stelleninserat* (svizzero) = un annuncio di lavoro pubblicato da un'azienda.","source":"hueber"}],"phrases":["A Online-Stellengesuch","B Stelleninserate","C Das persönliche Netzwerk","D Telefonische Bewerbung","E Spontanbewerbung"]},{"no":"2","instruction":"Yusuf hat entschieden, selbst aktiv zu werden, und hat ein Stellengesuch geschrieben. Lesen Sie seinen Text und unterstreichen Sie: – Wer und wie ist Yusuf? – Was kann er? – Was sucht er?","instruction_en":"Yusuf ha deciso di prendere l'iniziativa e ha scritto un annuncio in cui cerca lavoro. Leggi il suo testo e trova: chi è Yusuf e com'è, che cosa sa fare e che cosa cerca. Scrivi le parole giuste per ogni domanda.","reading":[{"text":"Suchen Sie einen engagierten Coiffeur, der kreativ und flexibel ist? Dann rufen Sie mich, 24, an. Ich biete sechs Jahre Berufserfahrung und diverse Weiterbildungen im Bereich Stilberatung. Ich suche eine Herausforderung, bei der ich Neues lernen und mich weiter spezialisieren kann."}],"items":[{"label":"1","lead":"Wer und wie ist Yusuf?","text":"","open":true,"solution":"ein engagierter Coiffeur, kreativ und flexibel, 24 Jahre alt","en":"un parrucchiere motivato, creativo e flessibile, 24 anni","why":"Chi è (professione, età) e com'è (aggettivi).","source":"hueber"},{"label":"2","lead":"Was kann er?","text":"","open":true,"solution":"sechs Jahre Berufserfahrung, diverse Weiterbildungen im Bereich Stilberatung","en":"sei anni di esperienza professionale, diversi corsi di perfezionamento nel campo della consulenza d'immagine","why":"Che cosa offre: esperienza e formazione.","source":"hueber"},{"label":"3","lead":"Was sucht er?","text":"","open":true,"solution":"eine Herausforderung, bei der er Neues lernen und sich weiter spezialisieren kann","en":"una sfida in cui possa imparare cose nuove e specializzarsi ulteriormente","why":"L'ultima frase: *Ich suche …*","source":"hueber"}]},{"no":"3","instruction":"Ein Stellengesuch im Internet aufgeben. Sie suchen eine neue Stelle. Machen Sie eine Tabelle. Schreiben Sie dann einen Profiltext wie in 2.","instruction_en":"Pubblica su internet un annuncio in cui cerchi lavoro. Stai cercando un nuovo impiego. Fai una tabella con tre colonne (Chi sono e come sono? Che cosa so fare? Che cosa cerco?), poi scrivi un testo di presentazione come quello di Yusuf in 2. La risposta modello è una possibilità.","phrases":["teamfähig/selbstständig/kontaktfreudig/zuverlässig/verantwortungsbewusst / … sein","gute Computer-/Sprachkenntnisse/Kenntnisse in … haben","gut mit … umgehen können","… Vollzeit/Teilzeit/auf Stundenbasis arbeiten","ab sofort / ab nächstem Monat / … suchen"],"example":[{"label":"Tabelle","text":"Wer und wie bin ich? flexibel, teamfähig, … | Was kann ich? … | Was suche ich? …"}],"items":[{"label":"1","lead":"Tabelle","text":"","open":true,"solution":"Wer und wie bin ich? flexibel, teamfähig, zuverlässig, kontaktfreudig | Was kann ich? gut mit Kunden umgehen, gute Computerkenntnisse, fliessend Deutsch und Englisch | Was suche ich? eine Teilzeitstelle ab nächstem Monat, ein internationales Team","en":"Chi sono e come sono? flessibile, capace di lavorare in team, affidabile, socievole | Che cosa so fare? trattare bene con i clienti, buone conoscenze informatiche, tedesco e inglese fluenti | Che cosa cerco? un posto a tempo parziale dal mese prossimo, un team internazionale","why":"Bastano poche parole chiave per colonna; usa le espressioni del riquadro.","source":"hueber"},{"label":"2","lead":"Profiltext","text":"","open":true,"solution":"Suchen Sie eine zuverlässige Verkäuferin, die teamfähig und kontaktfreudig ist? Ich kann gut mit Kunden umgehen, habe gute Computerkenntnisse und spreche fliessend Deutsch und Englisch. Ich suche ab nächstem Monat eine Teilzeitstelle in einem internationalen Team.","en":"Cercate una venditrice affidabile, capace di lavorare in team e socievole? So trattare bene con i clienti, ho buone conoscenze informatiche e parlo correntemente tedesco e inglese. Dal mese prossimo cerco un posto a tempo parziale in un team internazionale.","why":"Gli stessi tre passi di Yusuf: chi sei, che cosa sai fare, che cosa cerchi. Nella frase relativa *die* si riferisce a *Verkäuferin*.","source":"hueber"}]}]},{"page":"Test L4 · 19","heading":"Grammatik","heading_en":"Grammatica","exercises":[{"no":"1","instruction":"Wunsch und Realität?","instruction_en":"Desiderio e realtà?","part":"a","part_instruction":"Ergänzen Sie.","part_instruction_en":"Nina deve fare una cosa, ma ne farebbe volentieri un'altra. Scrivi che cosa preferirebbe fare con *würde* + le parole tra parentesi (con *lieber*, o *gern* nella frase 5).","example":[{"label":"1","lead":"Nina macht Diät. (Sahnetorte essen)","text":"Aber sie **würde lieber Sahnetorte essen**."}],"items":[{"label":"2","lead":"Nina muss für eine Sprachprüfung lernen. (Musik hören)","text":"Aber sie ___.","gaps":[["würde lieber Musik hören"]],"solution":"Aber sie **würde lieber Musik hören**.","en":"Ma preferirebbe ascoltare musica.","why":"*würde* in 2a posizione, *lieber* = piuttosto, infinito *hören* alla fine.","source":"k2"},{"label":"3","lead":"Nina muss ihre Kleider aufräumen. (mit ihrer Freundin telefonieren)","text":"Aber sie ___.","gaps":[["würde lieber mit ihrer Freundin telefonieren"]],"solution":"Aber sie **würde lieber mit ihrer Freundin telefonieren**.","en":"Ma preferirebbe telefonare alla sua amica.","why":"*würde* + *lieber* + infinito alla fine.","source":"k2"},{"label":"4","lead":"Nina arbeitet am Computer. (Computerspiele spielen)","text":"Aber sie ___.","gaps":[["würde lieber Computerspiele spielen"]],"solution":"Aber sie **würde lieber Computerspiele spielen**.","en":"Ma preferirebbe giocare ai videogiochi.","why":"*würde* + *lieber* + infinito alla fine.","source":"k2"},{"label":"5","lead":"Nina hat morgen sehr früh einen Termin. (bis spät in die Nacht lesen)","text":"Sie ___ gern ___.","gaps":[["würde aber"],["bis spät in die Nacht lesen"]],"solution":"Sie **würde aber** gern **bis spät in die Nacht lesen**.","en":"Però le piacerebbe leggere fino a tarda notte.","why":"Il libro stampa *gern*: *würde* + *gern* + infinito (un desiderio), con *aber* dopo il verbo.","source":"k2"},{"label":"6","lead":"Nina verbringt den Abend mit ihren Eltern. (tanzen gehen)","text":"Aber sie ___.","gaps":[["würde lieber tanzen gehen"]],"solution":"Aber sie **würde lieber tanzen gehen**.","en":"Ma preferirebbe andare a ballare.","why":"*würde* + *lieber*; entrambi gli infiniti *tanzen gehen* alla fine.","source":"k2"}]},{"no":"1","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Riscrivi le frasi di a come frasi ipotetiche irreali: *Wenn Nina nicht …, würde sie …*","example":[{"label":"1","text":"Wenn Nina nicht Diät machen würde, würde sie Sahnetorte essen."}],"items":[{"label":"2","text":"","accept":["Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören."],"solution":"**Wenn Nina nicht für eine Sprachprüfung lernen müsste, würde sie Musik hören.**","en":"Se Nina non dovesse studiare per un esame di lingua, ascolterebbe musica.","why":"*muss* → **müsste** alla fine della frase con *wenn*; la principale comincia con *würde*.","source":"kond"},{"label":"3","text":"","accept":["Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.","Wenn Nina ihre Kleider nicht aufräumen müsste, würde sie mit ihrer Freundin telefonieren."],"solution":"**Wenn Nina nicht ihre Kleider aufräumen müsste, würde sie mit ihrer Freundin telefonieren.**","en":"Se Nina non dovesse riordinare i suoi vestiti, telefonerebbe alla sua amica.","why":"*müsste* + infinito *aufräumen*: nella frase con *wenn* *müsste* va per ultimo.","source":"kond"},{"label":"4","text":"","accept":["Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.","Wenn Nina nicht am Computer arbeiten müsste, würde sie Computerspiele spielen."],"solution":"**Wenn Nina nicht am Computer arbeiten würde, würde sie Computerspiele spielen.**","en":"Se Nina non lavorasse al computer, giocherebbe ai videogiochi.","why":"La soluzione accetta *arbeiten würde* o *arbeiten müsste* nella frase con *wenn*."},{"label":"5","text":"","accept":["Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.","Wenn Nina morgen keinen Termin sehr früh hätte, würde sie bis spät in die Nacht lesen."],"solution":"**Wenn Nina morgen nicht sehr früh einen Termin hätte, würde sie bis spät in die Nacht lesen.**","en":"Se domani Nina non avesse un appuntamento molto presto, leggerebbe fino a tarda notte.","why":"*hat* → **hätte**, alla fine della frase con *wenn*."},{"label":"6","text":"","accept":["Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.","Wenn Nina den Abend nicht mit ihren Eltern verbringen müsste, würde sie tanzen gehen."],"solution":"**Wenn Nina den Abend nicht mit ihren Eltern verbringen würde, würde sie tanzen gehen.**","en":"Se Nina non passasse la serata con i suoi genitori, andrebbe a ballare.","why":"*würde* + infinito in entrambe le parti; *verbringen würde* alla fine della frase con *wenn*."}]},{"no":"2","instruction":"Ergänzen Sie: darum – weil – wegen.","instruction_en":"Completa con *darum*, *weil* o *wegen*. Ogni parola si usa due volte.","box":["darum","weil","wegen"],"items":[{"label":"a","text":"Viele Deutsche hören Majids Grammatikfehler nicht, ___ er eine sehr gute Aussprache hat.","gaps":[["weil"]],"solution":"Viele Deutsche hören Majids Grammatikfehler nicht, **weil** er eine sehr gute Aussprache hat.","en":"Molti tedeschi non sentono gli errori di grammatica di Majid, perché ha un'ottima pronuncia.","why":"Una causa, e il verbo *hat* è alla fine → **weil**.","source":"weil"},{"label":"b","text":"Mirko hat die Prüfung nicht bestanden, ___ will er jetzt einen Intensivkurs machen.","gaps":[["darum"]],"solution":"Mirko hat die Prüfung nicht bestanden, **darum** will er jetzt einen Intensivkurs machen.","en":"Mirko non ha superato l'esame, per questo ora vuole fare un corso intensivo.","why":"Una conseguenza, e il verbo *will* viene subito dopo lo spazio → **darum**.","source":"darum"},{"label":"c","text":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, ___ braucht er sehr gute Deutschkenntnisse.","gaps":[["darum"]],"solution":"Hassan will als Arzt in einem deutschen Krankenhaus arbeiten, **darum** braucht er sehr gute Deutschkenntnisse.","en":"Hassan vuole lavorare come medico in un ospedale tedesco, per questo ha bisogno di ottime conoscenze di tedesco.","why":"Conseguenza + verbo subito dopo lo spazio (*braucht er*) → **darum**.","source":"darum"},{"label":"d","text":"Camilla ist Managerin und kann ___ ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","gaps":[["wegen"]],"solution":"Camilla ist Managerin und kann **wegen** ihrer vielen Konferenzen nicht regelmässig am Deutschkurs teilnehmen.","en":"Camilla è manager e, a causa delle sue numerose conferenze, non può frequentare regolarmente il corso di tedesco.","why":"Segue un gruppo nominale (*ihrer vielen Konferenzen*, genitivo plurale) → **wegen**.","source":"wegen"},{"label":"e","text":"Boris wird ___ seines Akzents sofort als Russe erkannt.","gaps":[["wegen"]],"solution":"Boris wird **wegen** seines Akzents sofort als Russe erkannt.","en":"Boris viene subito riconosciuto come russo a causa del suo accento.","why":"Gruppo nominale al genitivo (*seines Akzents*) → **wegen**.","source":"wegen"},{"label":"f","text":"Anja würde gern Arabisch lernen, ___ sie die arabische Schrift so schön findet.","gaps":[["weil"]],"solution":"Anja würde gern Arabisch lernen, **weil** sie die arabische Schrift so schön findet.","en":"Ad Anja piacerebbe imparare l'arabo, perché trova così bella la scrittura araba.","why":"Causa con il verbo *findet* alla fine → **weil**.","source":"weil"}]}]},{"page":"Test L4 · 20","heading":"Wortschatz","heading_en":"Lessico","exercises":[{"no":"3","instruction":"Ordnen Sie zu.","instruction_en":"Completa il testo di Ferdez con le parole del riquadro. Ogni parola si usa una volta; quella barrata è usata nell'esempio. La scheda usa l'ortografia tedesca con l'Eszett; qui si usa l'ortografia svizzera con *ss* (*fliessend*).","box":["Akzent","fliessend","schimpfe","Muttersprache","Schrift","übersetzen","vergleiche"],"box_used":[3],"box_exact":true,"example":[{"label":"a","text":"Mein Name ist Ferdez. Ich komme aus Mazedonien. Meine **Muttersprache** ist Albanisch, aber ich spreche auch Mazedonisch."}],"items":[{"label":"b","text":"Im Mazedonischen wird die kyrillische ___ verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","gaps":[["Schrift"]],"solution":"Im Mazedonischen wird die kyrillische **Schrift** verwendet. Darum war es anfangs für mich nicht einfach, Deutsch zu schreiben.","en":"In macedone si usa l'alfabeto cirillico. Per questo all'inizio non è stato facile per me scrivere in tedesco.","why":"*die kyrillische Schrift* = l'alfabeto cirillico."},{"label":"c","text":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich ___ Deutsch, finde ich.","gaps":[["fliessend"]],"solution":"Seit acht Jahren lebe ich in Bayern. Inzwischen spreche ich **fliessend** Deutsch, finde ich.","en":"Vivo in Baviera da otto anni. Ormai parlo il tedesco correntemente, mi pare.","why":"*fliessend Deutsch sprechen* = parlare il tedesco correntemente."},{"label":"d","text":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen ___ habe!","gaps":[["Akzent"]],"solution":"Aber meine Kollegen aus Norddeutschland meinen, dass ich einen bayerischen **Akzent** habe!","en":"Ma i miei colleghi della Germania del Nord dicono che ho un accento bavarese!","why":"*einen … Akzent haben* = avere un accento; *einen bayerischen* → sostantivo maschile."},{"label":"e","text":"Wenn ich auf Bayerisch ___, lachen meine Kollegen sich kaputt.","gaps":[["schimpfe"]],"solution":"Wenn ich auf Bayerisch **schimpfe**, lachen meine Kollegen sich kaputt.","en":"Quando impreco in bavarese, i miei colleghi si sbellicano dalle risate.","why":"*schimpfen* = brontolare, imprecare; *ich schimpfe* alla fine della frase con *wenn*."},{"label":"f","text":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander ___, dann fällt mir auf, …","gaps":[["vergleiche"]],"solution":"Wenn ich Deutsch, Mazedonisch und Albanisch miteinander **vergleiche**, dann fällt mir auf, …","en":"Quando confronto tra loro il tedesco, il macedone e l'albanese, noto …","why":"*miteinander vergleichen* = confrontare tra loro; *ich vergleiche* alla fine della frase con *wenn*."},{"label":"g","text":"… dass man nicht alle Wörter wirklich gut in die andere Sprache ___ kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","gaps":[["übersetzen"]],"solution":"… dass man nicht alle Wörter wirklich gut in die andere Sprache **übersetzen** kann. Ich fühle mich heute in Mazedonien und in Deutschland zu Hause.","en":"… che non tutte le parole si possono tradurre davvero bene nell'altra lingua. Oggi mi sento a casa sia in Macedonia sia in Germania.","why":"*in eine Sprache übersetzen* = tradurre in una lingua; l'infinito sta prima di *kann*, alla fine della frase con *dass*."}]},{"no":"Pause","instruction":"Was bedeutet das? Kreuzen Sie an. «Lügen haben kurze Beine.»","instruction_en":"Che cosa significa il proverbio “Lügen haben kurze Beine” (le bugie hanno le gambe corte)? Scrivi A o B.","items":[{"label":"A/B","lead":"A Die Wahrheit kommt immer schnell ans Licht. Darum sollte man nicht lügen.  B Wer lügt, der bekommt zur Strafe kurze Beine.","text":"___","gaps":[["A"]],"solution":"**A**","en":"A: La verità viene sempre fuori in fretta. Per questo non si dovrebbe mentire.","why":"Una bugia non va lontano, come chi ha le gambe corte: viene scoperta presto. B è un gioco sul senso letterale delle parole."}]},{"no":"4","instruction":"Welches Wort passt auch? Notieren Sie.","instruction_en":"Quale parola del riquadro potrebbe sostituire la parola sottolineata? Scrivila. Ogni parola si usa una volta; quella barrata è usata nell'esempio. Le parole sottolineate sono in grassetto.","box":["allerdings","allmählich","aufschreiben","deswegen","ebenso","irgendwann","korrekt","stammt"],"box_used":[7],"box_exact":true,"example":[{"label":"a","text":"Meine Familie **kommt** aus Iran. → stammt"}],"items":[{"label":"b","lead":"Ich selbst bin **aber** in Mainz geboren.","text":"___","gaps":[["allerdings"]],"solution":"**allerdings**","en":"Io però sono nato a Magonza.","why":"*allerdings* = *aber*: limita quanto detto prima."},{"label":"c","lead":"Mit mir haben meine Eltern immer Deutsch gesprochen, **deshalb** kann ich leider nicht Farsi.","text":"___","gaps":[["deswegen"]],"solution":"**deswegen**","en":"I miei genitori hanno sempre parlato tedesco con me, per questo purtroppo non so parlare il farsi.","why":"*deswegen* = *deshalb* (conseguenza, il verbo segue subito dopo).","source":"deswegen"},{"label":"d","lead":"Jetzt nehme ich an einem Sprachkurs teil. Ich finde, Farsi ist **genauso** schwierig wie Deutsch.","text":"___","gaps":[["ebenso"]],"solution":"**ebenso**","en":"Adesso faccio un corso di lingua. Secondo me il farsi è difficile quanto il tedesco.","why":"*ebenso … wie* = *genauso … wie* = tanto … quanto."},{"label":"e","lead":"Besonders die Schrift! Ich bin ein Mensch, der sich alle neuen Wörter **notieren** muss.","text":"___","gaps":[["aufschreiben"]],"solution":"**aufschreiben**","en":"Soprattutto la scrittura! Sono una persona che deve scriversi tutte le parole nuove.","why":"*sich etwas notieren* = *sich etwas aufschreiben* = annotarsi qualcosa."},{"label":"f","lead":"Das ist schwierig, wenn man es in einer Schrift tun muss, die man auch erst **langsam** lernt.","text":"___","gaps":[["allmählich"]],"solution":"**allmählich**","en":"È difficile se devi farlo in una scrittura che stai imparando solo a poco a poco.","why":"*allmählich* = lentamente, passo dopo passo, gradualmente."},{"label":"g","lead":"Auch die Aussprache ist nicht leicht. Es gibt da diesen Laut «gh», den kann ich nicht **richtig** aussprechen.","text":"___","gaps":[["korrekt"]],"solution":"**korrekt**","en":"Anche la pronuncia non è facile. C'è questo suono “gh” che non riesco a pronunciare correttamente.","why":"*korrekt* = *richtig* = correttamente."},{"label":"h","lead":"**Eines Tages** klappt es – hoffe ich jedenfalls!","text":"___","gaps":[["irgendwann","Irgendwann"]],"solution":"**irgendwann**","en":"Prima o poi ci riuscirò – almeno lo spero!","why":"*irgendwann* = prima o poi, un giorno = *eines Tages*."}]}]},{"page":"Test L4 · 21","heading":"Lesen","heading_en":"Lettura","exercises":[{"no":"5","instruction":"Lesen Sie und kreuzen Sie an: Was ist richtig?","instruction_en":"Leggi le risposte al sondaggio “È importante imparare il tedesco?” e scegli la fine giusta per ogni frase. Scrivi la fine (o solo le sue prime parole).","reading":[{"label":"Brad, 30, aus Australien","text":"«Meine Freundin ist Deutsche. Deshalb bin ich vor einem Jahr nach Deutschland gekommen. Ich dachte, dass ich mit Englisch als Muttersprache keine Schwierigkeiten haben würde, einen Job zu finden. Aber immer wenn ich mich bewarb, bekam ich zur Antwort: Lernen Sie erst einmal richtig Deutsch. Dann können Sie wiederkommen. Offenbar glauben die Leute, dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht. Seit sechs Monaten besuche ich nun einen Deutschkurs.»"},{"label":"Alena, 24, aus Tschechien","text":"«Meine Grossmutter hat 30 Jahre in Wien gelebt. Ich habe sie als Kind oft besucht und Wien dabei sehr gut kennengelernt. Ich denke, ich habe in Wien bessere Karrierechancen als bei uns zu Hause. Darum habe ich jetzt das Zertifikat Deutsch gemacht. Mit dem Zertifikat habe ich bestimmt gute Chancen, wenn ich mich bei österreichischen Firmen bewerbe.»"},{"label":"Ewa, 23, aus Polen","text":"«Ich finde es aus historischen Gründen wichtig, Deutsch zu lernen. Denn Polen und Deutschland verbindet eine lange Geschichte, die nicht immer schön war. Aber gerade deshalb ist es wichtig, dass wir uns gegenseitig gut kennenlernen. Ich würde mir wünschen, dass auch mehr Deutsche sich für die polnische Sprache interessieren würden.»"},{"label":"Sopha, 32, aus Thailand","text":"«Mein Mann stammt aus Hessen. Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche. Aber jetzt gehen unsere beiden Söhne zur Schule, und ich habe gemerkt, dass meine Deutschkenntnisse nicht mehr ausreichend sind: In der Kommunikation mit der Klassenlehrerin und bei Elternabenden habe ich grosse Schwierigkeiten. Deshalb nehme ich jetzt an einem Deutschkurs für Eltern teil.»"},{"label":"Abdullah, 35, aus Bahrain","text":"«Ich arbeite seit ein paar Monaten an einer deutschen Klinik als Arzt. Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen. Im Krankenhaus brauche ich eigentlich gar nicht so viel Deutsch, denn für die Gespräche mit den Patienten genügt mein Deutsch, und die Kollegen sprechen alle sehr gut Englisch. Aber natürlich möchte ich die Sprache des Landes gut können, in dem ich lebe. Dann versteht man die Menschen und ihr Land besser. Aus diesem Grund lerne ich weiter Deutsch.»"},{"label":"Zeliha, 45, aus der Türkei","text":"«Ich bin nach Dortmund gekommen, als ich meinen Mann – einen Deutschtürken – geheiratet habe. Schnell kamen vier Kinder zur Welt. Das Geld war immer knapp bei uns, deswegen habe ich neben dem Haushalt und der Kindererziehung Schicht gearbeitet. Für einen Deutschkurs war nie Zeit und Geld da. Meine Kinder haben oft geschimpft, weil ich so schlecht Deutsch sprach. Jetzt lerne ich endlich richtig Deutsch, und meine Kinder helfen mir beim Lernen.»"}],"items":[{"label":"a","lead":"Wer gut Englisch kann, … ○ findet in Deutschland problemlos einen Job. ○ muss trotzdem gut Deutsch lernen.","text":"Wer gut Englisch kann, ___.","gaps":[["muss trotzdem gut Deutsch lernen","muss trotzdem"]],"solution":"Wer gut Englisch kann, **muss trotzdem gut Deutsch lernen**.","en":"Chi sa bene l'inglese deve comunque imparare bene il tedesco.","why":"A Brad, che è di madrelingua inglese, dicevano di continuo: *Lernen Sie erst einmal richtig Deutsch.*"},{"label":"b","lead":"Deutsche glauben offenbar, … ○ dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat. ○ dass man für eine Ausbildung Deutsch braucht.","text":"Deutsche glauben offenbar, ___.","gaps":[["dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat","dass man ohne perfektes Deutsch"]],"solution":"Deutsche glauben offenbar, **dass man ohne perfektes Deutsch keine beruflichen Kenntnisse hat**.","en":"A quanto pare i tedeschi credono che senza un tedesco perfetto non si abbiano competenze professionali.","why":"Brad: *… dass man auch keine Berufserfahrung hat, wenn man nicht perfekt Deutsch spricht.*"},{"label":"c","lead":"Alena hofft, dass sie mit dem Zertifikat Deutsch … ○ eine Arbeitsstelle in Österreich findet. ○ besser Bewerbungen schreiben kann.","text":"Alena hofft, dass sie mit dem Zertifikat Deutsch ___.","gaps":[["eine Arbeitsstelle in Österreich findet","eine Arbeitsstelle"]],"solution":"Alena hofft, dass sie mit dem Zertifikat Deutsch **eine Arbeitsstelle in Österreich findet**.","en":"Alena spera di trovare un lavoro in Austria con il certificato di tedesco.","why":"Alena si aspetta buone possibilità *bei österreichischen Firmen*."},{"label":"d","lead":"Als Polin will Ewa Deutsch können, denn … ○ Deutschland und Polen haben eine gemeinsame Geschichte. ○ sie hat viele Deutsche kennengelernt.","text":"Als Polin will Ewa Deutsch können, denn ___.","gaps":[["Deutschland und Polen haben eine gemeinsame Geschichte","Deutschland und Polen"]],"solution":"Als Polin will Ewa Deutsch können, denn **Deutschland und Polen haben eine gemeinsame Geschichte**.","en":"Da polacca, Ewa vuole sapere il tedesco, perché la Germania e la Polonia hanno una storia comune.","why":"Ewa: *Denn Polen und Deutschland verbindet eine lange Geschichte.*"},{"label":"e","lead":"Ewa findet es … ○ toll, dass so viel Deutsche Polnisch sprechen. ○ schade, dass sich nicht so viele Deutsche für Polnisch interessieren.","text":"Ewa findet es ___.","gaps":[["schade, dass sich nicht so viele Deutsche für Polnisch interessieren","schade"]],"solution":"Ewa findet es **schade, dass sich nicht so viele Deutsche für Polnisch interessieren**.","en":"Ewa trova un peccato che non molti tedeschi si interessino al polacco.","why":"Ewa vorrebbe che più tedeschi si interessassero al polacco."},{"label":"f","lead":"Sopha hat … ○ von ihrem Mann Deutsch gelernt. ○ hat einen Integrationskurs besucht.","text":"Sopha hat ___.","gaps":[["von ihrem Mann Deutsch gelernt","von ihrem Mann"]],"solution":"Sopha hat **von ihrem Mann Deutsch gelernt**.","en":"Sopha ha imparato il tedesco da suo marito.","why":"Sopha: *Ich habe von ihm das Deutsch gelernt, das ich im Alltag so brauche.*"},{"label":"g","lead":"Sie … ○ muss ihren Söhnen bei den Deutschhausaufgaben helfen. ○ hat Probleme, weil sie die Lehrer nicht gut genug versteht.","text":"Sie ___.","gaps":[["hat Probleme, weil sie die Lehrer nicht gut genug versteht","hat Probleme"]],"solution":"Sie **hat Probleme, weil sie die Lehrer nicht gut genug versteht**.","en":"Ha dei problemi perché non capisce abbastanza bene gli insegnanti.","why":"Con il docente di classe e alle riunioni dei genitori ha *grosse Schwierigkeiten*."},{"label":"h","lead":"Für die Arbeitserlaubnis … ○ werden gute Deutschkenntnisse erwartet. ○ braucht man gar nicht so gute Deutschkenntnisse.","text":"Für die Arbeitserlaubnis ___.","gaps":[["werden gute Deutschkenntnisse erwartet","werden gute"]],"solution":"Für die Arbeitserlaubnis **werden gute Deutschkenntnisse erwartet**.","en":"Per il permesso di lavoro si richiedono buone conoscenze di tedesco.","why":"Abdullah: *Für meine Arbeitserlaubnis musste ich sehr gute Deutschkenntnisse nachweisen.*"},{"label":"i","lead":"Abdullah will gut Deutsch können, weil … ○ die Patienten nicht Englisch sprechen. ○ er in Deutschland lebt.","text":"Abdullah will gut Deutsch können, weil ___.","gaps":[["er in Deutschland lebt"]],"solution":"Abdullah will gut Deutsch können, weil **er in Deutschland lebt**.","en":"Abdullah vuole sapere bene il tedesco perché vive in Germania.","why":"Vuole sapere la lingua *des Landes …, in dem ich lebe*; per i pazienti il suo tedesco basta già."},{"label":"j","lead":"Zeliha lernt Deutsch … ○ , weil sie Geld verdienen muss. ○ wegen ihrer Kinder.","text":"Zeliha lernt Deutsch ___.","gaps":[["wegen ihrer Kinder"]],"solution":"Zeliha lernt Deutsch **wegen ihrer Kinder**.","en":"Zeliha impara il tedesco per via dei suoi figli.","why":"I suoi figli si lamentavano che il suo tedesco fosse così scarso, e ora la aiutano a imparare."}]}]},{"page":"Test L4 · 22","heading":"Sprechen","heading_en":"Parlare","exercises":[{"no":"7","instruction":"Welche Reaktion passt am besten? Verbinden Sie.","instruction_en":"Quale risposta è la più adatta? Scrivi dopo ogni frase il numero della risposta (1–6). (L'esercizio 6 di questa pagina è un ascolto ed è omesso.)","example":[{"label":"a","text":"Darf ich Sie kurz etwas fragen? → **2** Natürlich, gern."}],"items":[{"label":"b","text":"Mein Name ist Kranitzky-Krampe. → ___","gaps":[["5"]],"solution":"Mein Name ist Kranitzky-Krampe. → **5**","en":"Mi chiamo Kranitzky-Krampe. → 5 Scusi, come ha detto che si chiama?","why":"Un nome lungo e insolito: chiedi di ripetere."},{"label":"c","text":"Zu Kleidung kann man auch «Klamotten» sagen. → ___","gaps":[["4"]],"solution":"Zu Kleidung kann man auch «Klamotten» sagen. → **4**","en":"Per i vestiti si può dire anche “Klamotten”. → 4 Questa parola non l'ho mai sentita.","why":"Una parola nuova (colloquiale): *Das Wort habe ich noch nie gehört.*"},{"label":"d","text":"Was bedeutet dieses Wort? → ___","gaps":[["1"]],"solution":"Was bedeutet dieses Wort? → **1**","en":"Che cosa significa questa parola? → 1 Purtroppo non lo so neanch'io.","why":"Una risposta a una domanda a cui non sai rispondere."},{"label":"e","text":"Da habe ich echt Schwein gehabt. → ___","gaps":[["6"]],"solution":"Da habe ich echt Schwein gehabt. → **6**","en":"Lì ho avuto proprio fortuna. → 6 Ho capito bene: ha avuto fortuna?","why":"*Schwein haben* (colloquiale) = avere fortuna; verifichi di aver capito."},{"label":"f","text":"Könnten Sie bitte langsamer sprechen? → ___","gaps":[["3"]],"solution":"Könnten Sie bitte langsamer sprechen? → **3**","en":"Potrebbe parlare più lentamente, per favore? → 3 Va bene, ci provo.","why":"Una risposta a una richiesta."}],"phrases":["1 Das weiss ich leider auch nicht.","2 Natürlich, gern.","3 Okay, ich versuche es.","4 Das Wort habe ich noch nie gehört.","5 Wie war bitte Ihr Name?","6 Habe ich das richtig verstanden: Du hattest Glück?"]},{"no":"8","instruction":"Schreiben Sie die Fragen.","instruction_en":"Scrivi le domande indirette con le parole tra parentesi. Nella domanda indiretta il verbo va alla fine.","example":[{"label":"a","lead":"(Bild: Ein Mann und eine Frau lesen zusammen in einem Buch.) Weisst du vielleicht, … (Aufgabe – wie?)","text":"Weisst du vielleicht, **wie ich diese Aufgaben machen muss**?"}],"items":[{"label":"b","lead":"(Bild: Zwei Männer stehen mit ihren Mülltonnen auf der Strasse.) Können Sie mir sagen, … (Müll – wohin?)","text":"Können Sie mir sagen, ___?","gaps":[["wohin ich den Müll bringen muss","wohin ich den Müll bringen soll"]],"solution":"Können Sie mir sagen, **wohin ich den Müll bringen muss**?","en":"Può dirmi dove devo portare la spazzatura?","why":"*wohin* introduce la domanda indiretta; il verbo coniugato *muss* va alla fine."},{"label":"c","lead":"(Bild: Eine Frau sitzt beim Arzt.) Können Sie mir bitte sagen, … (Schmerzen – wo?)","text":"Können Sie mir bitte sagen, ___?","gaps":[["wo Sie Schmerzen haben"]],"solution":"Können Sie mir bitte sagen, **wo Sie Schmerzen haben**?","en":"Può dirmi, per favore, dove sente dolore?","why":"Il medico chiede: *wo* + soggetto + verbo alla fine (*haben*)."},{"label":"d","lead":"(Bild: Eine Frau fragt einen Mann im Zug.) Wissen Sie vielleicht, … (Zug nach Berlin – ob?)","text":"Wissen Sie vielleicht, ___?","gaps":[["ob der Zug nach Berlin fährt","ob dieser Zug nach Berlin fährt","ob das der Zug nach Berlin ist"]],"solution":"Wissen Sie vielleicht, **ob der Zug nach Berlin fährt**?","en":"Sa per caso se il treno va a Berlino?","why":"Una domanda sì/no diventa indiretta con *ob*; il verbo *fährt* va alla fine."}]}]},{"page":"Test L4 · 23","heading":"Schreiben","heading_en":"Scrittura","exercises":[{"no":"9","instruction":"Wählen Sie eine Sprache, die Sie gern lernen würden, und schreiben Sie eine Nachricht an die Sprachschule. – Schreiben Sie, für welche Sprache Sie sich interessieren. – Sagen Sie, wann und wie oft pro Woche Sie Zeit für den Kurs haben. – Fragen Sie, zu welchen Terminen/Zeiten die Sprachschule einen Kurs in Ihrer Wunschsprache anbietet. – Fragen Sie auch nach den Kursgebühren und der Kursdauer. – Bitten Sie um eine Antwort. – Denken Sie an die passende Anrede und den Gruss am Ende.","instruction_en":"Scegli una lingua che ti piacerebbe imparare e scrivi un messaggio alla scuola di lingue: quale lingua, quando e quante volte alla settimana hai tempo, quali date e orari offrono per il corso, il costo e la durata del corso; chiedi una risposta e usa un saluto iniziale e finale adatti. La risposta modello segue la soluzione ufficiale.","phrases":["… Damen und Herren,","ich würde gern …","Ich … und …","Bitte teilen Sie mir mit, …","Auch müsste ich wissen, …","Mit …","**LERNTIPP** Was sagt man in dieser Situation? Notieren und lernen Sie nicht nur einzelne neue Wörter. Wenn Sie sich zu verschiedenen Situationen passende Sätze und Ausdrücke aufschreiben, fühlen Sie sich in Gesprächen sicherer. Benutzen Sie zum Beispiel Karteikärtchen und schreiben Sie eine Situation oder ein Thema auf die Vorderseite: «nachfragen». Schreiben Sie Beispiele zum Thema auf die Rückseite und lernen Sie diese auswendig: «Was meinen Sie mit …?», «Was bedeutet …?» … Diese Methode eignet sich auch gut, wenn Sie sich auf ein Gespräch vorbereiten möchten. Überlegen Sie, was Sie sagen oder fragen möchten und was der Gesprächspartner sagen oder fragen könnte. Sicher können Sie während des Gesprächs einen Ihrer geübten Sätze anwenden."],"items":[{"label":"9","text":"","open":true,"solution":"**Sehr geehrte** Damen und Herren, ich würde gern **Neugriechisch lernen**. Ich **habe von Montag bis Donnerstag abends Zeit** und **könnte zweimal pro Woche kommen**. Bitte teilen Sie mir mit, **zu welchen Zeiten Sie einen Neugriechisch-Kurs anbieten**. Auch müsste ich wissen, **wie viel der Kurs kostet und wie lange er dauert**. **Ich bitte Sie um eine kurze Antwort.** Mit **freundlichen Grüssen** …","en":"Gentili signore e signori, vorrei imparare il greco moderno. Ho tempo dal lunedì al giovedì di sera e potrei venire due volte alla settimana. Vi prego di comunicarmi in quali orari offrite un corso di greco moderno. Avrei anche bisogno di sapere quanto costa il corso e quanto dura. Vi chiedo una breve risposta. Cordiali saluti …","why":"Lettera formale: *Sehr geehrte Damen und Herren* … *Mit freundlichen Grüssen*. Le domande sono indirette (*zu welchen Zeiten …, wie viel …, wie lange …*): verbo alla fine."}]}]}]},{"id":"04-zu-infinitiv-bewerbung","no":4,"title":"Infinitiv mit zu · Bewerbung · Test Lektion 5","title_en":"Infinito con zu, la lettera di candidatura, chiacchiere sul lavoro · Test della lezione 5","added":"2026-11-12","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 5","sources":[{"id":"hueber","title":"Hueber: Schritte plus Neu 5 Schweiz, Lösungen Arbeitsbuch (soluzioni ufficiali, Lektion 5)","url":"https://www.hueber.de/media/36/Schritte-plus-Neu-5_CH_Loesungen_AB.pdf"},{"id":"g98","title":"grammis: Verben mit einem Infinitiv mit oder ohne zu (verbi modali senza zu; brauchen con zu)","url":"https://grammis.ids-mannheim.de/fragen/98"},{"id":"g6865","title":"grammis: Vertiefung: Infinitivsätze (frasi infinitive con zu)","url":"https://grammis.ids-mannheim.de/progr@mm/6865"},{"id":"g4069","title":"grammis: Verbflexion (zu tra la particella e il verbo: anzurufen)","url":"https://grammis.ids-mannheim.de/progr@mm/4069"},{"id":"g6393","title":"grammis: Alternation von zu- und dass-Komplementen (frase con dass o zu + infinito)","url":"https://grammis.ids-mannheim.de/korpusgrammatik/6393"},{"id":"g299310","title":"grammis: während (Präposition, con il genitivo)","url":"https://grammis.ids-mannheim.de/praepositionen/299310"},{"id":"prep","title":"grammis: Präpositionalphrase (le preposizioni e i casi che reggono)","url":"https://grammis.ids-mannheim.de/kontrastive-grammatik/5747"}],"pages":[{"page":"AB 140","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Comincia finalmente a scrivere candidature!","exercises":[{"no":"1","tag":"A1","instruction":"Ich habe leider keine Zeit …","instruction_en":"Purtroppo non ho tempo …","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Completa ogni frase con un verbo del riquadro. Ognuno si usa una volta; quello barrato è usato nell'esempio.","box":["mitzuarbeiten","auszuschalten","zu erklären","mitzukommen","zu sein","zu gehen"],"box_used":[5],"box_exact":true,"example":[{"label":"1","text":"Erlaubst du uns, ins Kino **zu gehen**?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd ___.","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, den Herd **auszuschalten**.","en":"Per favore non dimenticate di spegnere il fornello.","why":"*ausschalten* è separabile, quindi *zu* va tra la particella e il verbo: *aus**zu**schalten*.","source":"g4069"},{"label":"3","text":"Ich habe Angst, nachts allein ___.","gaps":[["zu sein"]],"solution":"Ich habe Angst, nachts allein **zu sein**.","en":"Ho paura di stare da solo di notte.","why":"*Angst haben* + *zu* + infinito; *sein* è un verbo semplice, quindi *zu* sta davanti.","source":"g6865"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein ___.","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein **mitzuarbeiten**.","en":"No, non è troppo stressante collaborare in un'associazione.","why":"*Es ist* + aggettivo + *zu* + infinito. *mitarbeiten* è separabile: *mit**zu**arbeiten*. (Qui il primo *zu* significa \"troppo\".)","source":"g4069"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg ___.","gaps":[["zu erklären"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg **zu erklären**.","en":"Purtroppo non ho tempo di spiegarLe la strada.","why":"*keine Zeit haben* + *zu* + infinito. *erklären* non è separabile (*er-* è un prefisso inseparabile), quindi *zu* sta davanti.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, ins Training ___.","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, ins Training **mitzukommen**.","en":"Oggi non ho voglia di venire all'allenamento.","why":"*keine Lust haben* + *zu* + infinito; *mitkommen* è separabile: *mit**zu**kommen*.","source":"g4069"}]},{"no":"1","part":"b","part_instruction":"Nach welchen Ausdrücken folgt *zu*? Markieren Sie in a wie im Beispiel.","part_instruction_en":"Quali espressioni sono seguite da *zu*? Scrivi l'espressione (il verbo o verbo + sostantivo/aggettivo) che richiede *zu* in ogni frase di a.","example":[{"label":"1","text":"**Erlaubst** du uns, ins Kino zu gehen?"}],"items":[{"label":"2","text":"Vergesst bitte nicht, den Herd auszuschalten. → ___","gaps":[["Vergesst","Vergesst bitte nicht","vergessen","vergesst nicht"]],"solution":"Vergesst bitte nicht, den Herd auszuschalten. → **Vergesst**","en":"Per favore non dimenticate di spegnere il fornello. → dimenticare","why":"Il verbo *vergessen* (qui *Vergesst*) è seguito da *zu* + infinito.","source":"hueber"},{"label":"3","text":"Ich habe Angst, nachts allein zu sein. → ___","gaps":[["habe Angst","Angst haben","Ich habe Angst","Angst"]],"solution":"Ich habe Angst, nachts allein zu sein. → **habe Angst**","en":"Ho paura di stare da solo di notte. → avere paura","why":"*haben* + sostantivo (*Angst, Lust, Zeit, Interesse*) è seguito da *zu* + infinito.","source":"hueber"},{"label":"4","text":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → ___","gaps":[["ist nicht zu stressig","es ist nicht zu stressig","ist stressig","stressig sein","es ist stressig","stressig"]],"solution":"Nein, es ist nicht zu stressig, in einem Verein mitzuarbeiten. → **ist nicht zu stressig**","en":"No, non è troppo stressante collaborare in un'associazione. → è (non troppo) stressante","why":"*Es ist* + aggettivo è seguito da *zu* + infinito.","source":"hueber"},{"label":"5","text":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → ___","gaps":[["habe leider keine Zeit","habe keine Zeit","keine Zeit haben","Zeit haben","keine Zeit","Zeit"]],"solution":"Ich habe leider keine Zeit, Ihnen den Weg zu erklären. → **habe leider keine Zeit**","en":"Purtroppo non ho tempo di spiegarLe la strada. → (non) avere tempo","why":"*Zeit haben* (qui *keine Zeit*) è seguito da *zu* + infinito.","source":"hueber"},{"label":"6","text":"Ich habe heute keine Lust, ins Training mitzukommen. → ___","gaps":[["habe heute keine Lust","habe keine Lust","keine Lust haben","Lust haben","keine Lust","Lust"]],"solution":"Ich habe heute keine Lust, ins Training mitzukommen. → **habe heute keine Lust**","en":"Oggi non ho voglia di venire all'allenamento. → (non) avere voglia","why":"*Lust haben* (qui *keine Lust*) è seguito da *zu* + infinito.","source":"hueber"}]},{"no":"1","part":"c","part_instruction":"Wo steht *zu*? Ergänzen Sie die Tabelle mit den Sätzen aus a.","part_instruction_en":"Dove va *zu*? La tabella ha tre colonne: l'inizio della frase, la parte centrale, poi il verbo con *zu*. Inserisci le frasi di a con un verbo separabile (2, 4, 6) e scrivi l'ultima colonna. Le parti del verbo sono tra parentesi.","example":[{"label":"1","text":"Erlaubst du uns, | ins Kino | **zu gehen**? (gehen)"}],"items":[{"label":"2","text":"Vergesst bitte nicht, | den Herd | ___. (aus·schalten)","gaps":[["auszuschalten"]],"solution":"Vergesst bitte nicht, | den Herd | **auszuschalten**. (aus·schalten)","en":"Per favore non dimenticate | il fornello | di spegnere.","why":"Verbo separabile: *zu* va tra *aus* e *schalten*, e si scrive tutto attaccato.","source":"g4069"},{"label":"4","text":"Nein, es ist nicht zu stressig, | in einem Verein | ___. (mit·arbeiten)","gaps":[["mitzuarbeiten"]],"solution":"Nein, es ist nicht zu stressig, | in einem Verein | **mitzuarbeiten**. (mit·arbeiten)","en":"No, non è troppo stressante | in un'associazione | collaborare.","why":"Verbo separabile: *mit* + *zu* + *arbeiten*, scritto come una sola parola.","source":"g4069"},{"label":"6","text":"Ich habe heute keine Lust, | ins Training | ___. (mit·kommen)","gaps":[["mitzukommen"]],"solution":"Ich habe heute keine Lust, | ins Training | **mitzukommen**. (mit·kommen)","en":"Oggi non ho voglia | all'allenamento | di venire.","why":"Verbo separabile: *mit* + *zu* + *kommen*, scritto come una sola parola.","source":"g4069"}]},{"no":"2","tag":"A1","instruction":"Was ist richtig? Kreuzen Sie an.","instruction_en":"Che cosa è giusto? Scrivi *zu* se la frase ha bisogno di *zu*, oppure *–* (un trattino) se non serve niente.","example":[{"label":"a","text":"Ich höre nicht auf, nach meinem Traumjob **zu** suchen."}],"items":[{"label":"b","text":"Möchten Sie nicht auch in Ihrem Traumberuf ___ arbeiten?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Möchten Sie nicht auch in Ihrem Traumberuf **–** arbeiten?","en":"Non Le piacerebbe lavorare anche Lei nella professione dei Suoi sogni?","why":"Dopo un verbo modale (*möchten*) l'infinito non prende mai *zu*.","source":"g98"},{"label":"c","text":"Ich könnte mir gut vorstellen, ein Handwerk ___ lernen.","gaps":[["zu"]],"solution":"Ich könnte mir gut vorstellen, ein Handwerk **zu** lernen.","en":"Potrei benissimo immaginare di imparare un mestiere.","why":"*sich vorstellen können* introduce una seconda frase dopo la virgola, con *zu* + infinito. *könnte* si riferisce solo a *vorstellen*.","source":"g6865"},{"label":"d","text":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz ___ finden.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Mit einer Ausbildung als Handwerker kann man einen guten Arbeitsplatz **–** finden.","en":"Con una formazione da artigiano si può trovare un buon posto di lavoro.","why":"Verbo modale *kann* + infinito senza *zu*.","source":"g98"},{"label":"e","text":"Könnten Sie mir bei der Berufswahl ___ helfen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Könnten Sie mir bei der Berufswahl **–** helfen?","en":"Potrebbe aiutarmi a scegliere una professione?","why":"*Könnten* è un verbo modale (Konjunktiv II di *können*): niente *zu*.","source":"g98"},{"label":"f","text":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten ___ informieren.","gaps":[["zu"]],"solution":"Es ist ziemlich stressig, sich über die beruflichen Möglichkeiten **zu** informieren.","en":"È piuttosto stressante informarsi sulle possibilità professionali.","why":"*Es ist* + aggettivo (*stressig*) + *zu* + infinito.","source":"g6865"}]},{"no":"3","tag":"A1","marker":"◇","instruction":"Ergänzen Sie: *zu* oder *–*.","instruction_en":"Completa con *zu*, oppure scrivi *–* (un trattino) dove non manca niente.","example":[{"label":"a","text":"Ich habe schon einmal angefangen, das Bewerbungsgespräch vor**zu**bereiten."}],"items":[{"label":"b","text":"Wir dürfen den Geburtstag der Chefin nicht ___ vergessen!","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Wir dürfen den Geburtstag der Chefin nicht **–** vergessen!","en":"Non dobbiamo dimenticare il compleanno della capa!","why":"Verbo modale *dürfen* + infinito senza *zu*.","source":"g98"},{"label":"c","text":"Es ist nicht leicht, eine Stelle in seinem Traumjob ___ finden.","gaps":[["zu"]],"solution":"Es ist nicht leicht, eine Stelle in seinem Traumjob **zu** finden.","en":"Non è facile trovare un posto nel lavoro dei propri sogni.","why":"*Es ist nicht leicht* + *zu* + infinito.","source":"g6865"},{"label":"d","text":"Ich würde am liebsten in einem Team ___ arbeiten.","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Ich würde am liebsten in einem Team **–** arbeiten.","en":"Più di tutto mi piacerebbe lavorare in un team.","why":"*würde* + infinito (Konjunktiv II) funziona come un verbo modale: niente *zu*.","source":"g98"},{"label":"e","text":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung ___ helfen?","gaps":[["zu"]],"solution":"Hast du vielleicht kurz Zeit, mir bei meiner Bewerbung **zu** helfen?","en":"Hai un attimo di tempo per aiutarmi con la mia candidatura?","why":"*Zeit haben* + *zu* + infinito.","source":"g6865"},{"label":"f","text":"Kannst du dir eine Lehre im Büro vor ___ stellen?","gaps":[["–","-","nichts","kein zu","ohne zu","x"]],"solution":"Kannst du dir eine Lehre im Büro vor **–** stellen?","en":"Riesci a immaginarti un apprendistato in ufficio?","why":"*Kannst* è un verbo modale, quindi non si inserisce niente: *vorstellen* si scrive come una sola parola.","source":"g98"}]}]},{"page":"AB 141","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Comincia finalmente a scrivere candidature!","exercises":[{"no":"4","instruction":"Schreiben Sie Sätze.","instruction_en":"Scrivi frasi sulla tua vita professionale: combina un'espressione del riquadro di sinistra con un'attività del riquadro di destra. Le parole barrate sono usate nell'esempio. La risposta modello è una possibilità.","box":["(keine) Lust haben","möchten","hoffen","Freude machen","können","sich vorstellen können","würde … gern","anstrengend sein","…","ein halbes Jahr um die Welt reisen","am Abend arbeiten","(nicht) immer dasselbe machen","sehr gut selbstständig arbeiten","mit netten Kollegen zusammenarbeiten","Neues lernen","wenig Freizeit haben"],"box_used":[0,1,10],"example":[{"label":"Beispiel","text":"Ich habe keine Lust, am Abend **zu arbeiten**. Ich möchte in meinem Berufsleben …"}],"items":[{"label":"1","lead":"Ihre Sätze","text":"","open":true,"solution":"Ich möchte in meinem Berufsleben nicht immer dasselbe machen. Ich hoffe, mit netten Kollegen zusammenzuarbeiten. Es macht mir Freude, Neues zu lernen. Ich kann sehr gut selbstständig arbeiten. Es ist anstrengend, wenig Freizeit zu haben. Ich würde gern ein halbes Jahr um die Welt reisen.","en":"Nella mia vita professionale non voglio fare sempre la stessa cosa. Spero di lavorare con colleghi simpatici. Mi fa piacere imparare cose nuove. So lavorare molto bene in autonomia. È faticoso avere poco tempo libero. Mi piacerebbe viaggiare per il mondo per sei mesi.","why":"Dopo *hoffen, Freude machen, sich vorstellen können, anstrengend sein, Lust haben* usa *zu* + infinito (verbi separabili: *zusammen**zu**arbeiten*). Dopo *möchten, können, würde … gern* niente *zu*.","source":"g98"}]},{"no":"5","instruction":"Ordnen Sie zu und schreiben Sie Sätze mit *zu*.","instruction_en":"Abbina ogni affermazione a un verbo del riquadro e scrivi una frase con *zu* + infinito. Il verbo barrato è usato nell'esempio.","box":["sich vorstellen können","versuchen","aufhören","versprechen","vorhaben"],"box_used":[1],"example":[{"label":"a","lead":"Morgen will ich pünktlich sein. Vielleicht!","text":"versuchen: Morgen versuche ich, pünktlich **zu sein**."}],"items":[{"label":"b","lead":"Ich hole dich morgen ab. Ganz sicher.","text":"","accept":["Ich verspreche, dich morgen abzuholen.","Ich verspreche dir, dich morgen abzuholen.","versprechen: Ich verspreche, dich morgen abzuholen."],"solution":"**Ich verspreche, dich morgen abzuholen.**","en":"Prometto di venirti a prendere domani.","why":"\"Sicuramente\" = una promessa: *versprechen*. *abholen* è separabile: *ab**zu**holen*.","source":"hueber"},{"label":"c","lead":"Einen interessanten Job finden! Das ist mein Plan.","text":"","accept":["Ich habe vor, einen interessanten Job zu finden.","vorhaben: Ich habe vor, einen interessanten Job zu finden."],"solution":"**Ich habe vor, einen interessanten Job zu finden.**","en":"Ho intenzione di trovare un lavoro interessante.","why":"Un progetto = *vorhaben*: *Ich habe vor, … zu finden.* La particella *vor* va alla fine della frase principale.","source":"hueber"},{"label":"d","lead":"Ein Handwerk lernen? Ja, warum eigentlich nicht?","text":"","accept":["Ich kann mir vorstellen, ein Handwerk zu lernen.","Ich kann mir gut vorstellen, ein Handwerk zu lernen.","sich vorstellen können: Ich kann mir vorstellen, ein Handwerk zu lernen."],"solution":"**Ich kann mir vorstellen, ein Handwerk zu lernen.**","en":"Riesco a immaginarmi di imparare un mestiere.","why":"\"Perché no?\" = riesci a immaginarlo: *Ich kann mir vorstellen, … zu lernen.*","source":"hueber"},{"label":"e","lead":"Ich arbeite als Pflegefachmann. Aber nur noch bis Ende Monat.","text":"","accept":["Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.","Ende Monat höre ich auf, als Pflegefachmann zu arbeiten.","aufhören: Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten."],"solution":"**Ich höre Ende Monat auf, als Pflegefachmann zu arbeiten.**","en":"A fine mese smetto di lavorare come infermiere.","why":"\"Solo fino a fine mese\" = smettere: *aufhören*, con *auf* alla fine della frase principale, prima della virgola.","source":"hueber"}]},{"no":"6","instruction":"Markieren Sie noch neun Wörter und ordnen Sie zu.","instruction_en":"Trova altre nove parole nella griglia di lettere e inseriscile negli annunci di lavoro A–C. Le parole cerchiate (*Bewerbung, Tätigkeit*) sono gli esempi. Scrivi ogni parola nella forma richiesta dalla frase (iniziale maiuscola per i sostantivi).","reading":[{"label":"Buchstabengitter","text":"AUFGABENSGBESCHÄFTIGSTIBEWERBUNGTERWARTENZTÄTIGKEIT\nBEWERBUNGSUNTERLAGENZYTWHANDELUTPOÜKENNTNISSENKWAQ\nUNTERSTÜTZUNGMUSJÄMTILVORAUSSETZUNGDUQSCHRIFTLICHLW"},{"label":"A  Heimpflegedienst Bachmann","text":"Wir suchen für 15 Stunden pro Woche … (1) für den Patientenfahrdienst.\n… (2) für die Tätigkeit ist: + Führerausweis Kategorie B + … (3) in Erster Hilfe + Freude an der Arbeit mit Menschen\nEs … (4) Sie: + interessante … (5) + Weiterbildungsmöglichkeiten + ein angenehmes Betriebsklima\nBitte schicken Sie Ihre Bewerbung an personal@hpfd-bachmann.ch"},{"label":"B","text":"Detailhandelsassistent/in für unser kleines Modegeschäft gesucht!\nErfahrung im … (1) und Verkauf von Vorteil. Wenden Sie sich bei Fragen … (2) oder telefonisch an Frau Kleinert: kleinert@neuemode.ch / 031 330 110 10."},{"label":"C","text":"HAST DU HANDWERKLICHES TALENT?\n… (1) du dich gern mit Holz? Dann komm zu uns! Wir bieten dir eine Lehrstelle als Schreiner/in EFZ.\nSchick deine … (2) noch heute an: Clemens Meier (cl.meier@schreinerei-meier.ch)"}],"example":[{"label":"A","text":"… für die **Tätigkeit** ist: … Bitte schicken Sie Ihre **Bewerbung** an personal@hpfd-bachmann.ch"}],"items":[{"label":"A1","text":"Wir suchen für 15 Stunden pro Woche ___ für den Patientenfahrdienst.","gaps":[["Unterstützung"]],"solution":"Wir suchen für 15 Stunden pro Woche **Unterstützung** für den Patientenfahrdienst.","en":"Cerchiamo un aiuto per il servizio di trasporto pazienti, 15 ore alla settimana.","why":"*die Unterstützung* = sostegno, aiuto; qui indica una persona che aiuta.","source":"hueber"},{"label":"A2","text":"___ für die Tätigkeit ist: Führerausweis Kategorie B","gaps":[["Voraussetzung"]],"solution":"**Voraussetzung** für die Tätigkeit ist: Führerausweis Kategorie B","en":"Requisito per l'attività: patente di guida categoria B","why":"*die Voraussetzung* = requisito, condizione. *der Führerausweis* è la parola svizzera per patente di guida.","source":"hueber"},{"label":"A3","text":"+ ___ in Erster Hilfe","gaps":[["Kenntnisse"]],"solution":"+ **Kenntnisse** in Erster Hilfe","en":"+ conoscenze di primo soccorso","why":"*Kenntnisse in* + dativo = conoscenze di / competenze in.","source":"hueber"},{"label":"A4","text":"Es ___ Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","gaps":[["erwarten"]],"solution":"Es **erwarten** Sie: interessante Aufgaben, Weiterbildungsmöglichkeiten, ein angenehmes Betriebsklima","en":"La attendono: compiti interessanti, possibilità di formazione continua, un piacevole clima aziendale","why":"*Es erwarten Sie …* = \"La attendono …\"; *es* occupa solo la posizione 1, il verbo concorda con il soggetto plurale che segue.","source":"hueber"},{"label":"A5","text":"+ interessante ___","gaps":[["Aufgaben"]],"solution":"+ interessante **Aufgaben**","en":"+ compiti interessanti","why":"*die Aufgabe, die Aufgaben* = compito, compiti; *interessante* indica un plurale.","source":"hueber"},{"label":"B1","text":"Erfahrung im ___ und Verkauf von Vorteil.","gaps":[["Handel"]],"solution":"Erfahrung im **Handel** und Verkauf von Vorteil.","en":"Esperienza nel commercio e nella vendita costituisce un vantaggio.","why":"*der Handel* = commercio; *im* = *in dem*. *von Vorteil* = un vantaggio.","source":"hueber"},{"label":"B2","text":"Wenden Sie sich bei Fragen ___ oder telefonisch an Frau Kleinert.","gaps":[["schriftlich"]],"solution":"Wenden Sie sich bei Fragen **schriftlich** oder telefonisch an Frau Kleinert.","en":"Per domande si rivolga per iscritto o per telefono alla signora Kleinert.","why":"*schriftlich oder telefonisch* = per iscritto o per telefono.","source":"hueber"},{"label":"C1","text":"___ du dich gern mit Holz?","gaps":[["Beschäftigst"]],"solution":"**Beschäftigst** du dich gern mit Holz?","en":"Ti piace lavorare con il legno?","why":"*sich beschäftigen mit* = occuparsi di; *du beschäftigst dich*. Apre la domanda sì/no, quindi ha l'iniziale maiuscola.","source":"hueber"},{"label":"C2","text":"Schick deine ___ noch heute an: Clemens Meier","gaps":[["Bewerbungsunterlagen"]],"solution":"Schick deine **Bewerbungsunterlagen** noch heute an: Clemens Meier","en":"Manda oggi stesso i tuoi documenti di candidatura a: Clemens Meier","why":"*die Bewerbungsunterlagen* (plurale) = curriculum, certificati e lettera insieme.","source":"hueber"}]}]},{"page":"AB 142","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Comincia finalmente a scrivere candidature!","exercises":[{"no":"7","tag":"A2","instruction":"Ergänzen Sie in der richtigen Form: *brauchen – müssen*.","instruction_en":"Completa con la forma giusta di *brauchen* o *müssen*. Consiglio: *brauchen* va con *zu* + infinito e con una negazione o *nur*; *müssen* non vuole mai *zu*.","example":[{"label":"a","text":"Ich **brauche** nur die neuen Wörter zu lernen, dann schaffe ich die Prüfung schon."}],"items":[{"label":"b","text":"Dein Zeugnis ist doch so gut. Du ___ dir wirklich keine Gedanken um einen Job zu machen.","gaps":[["brauchst"]],"solution":"Dein Zeugnis ist doch so gut. Du **brauchst** dir wirklich keine Gedanken um einen Job zu machen.","en":"La tua pagella è così buona. Non devi davvero preoccuparti per un lavoro.","why":"Negazione (*keine*) + *zu machen*: *brauchen … zu* = *nicht müssen*.","source":"g98"},{"label":"c","text":"Wenn sie nur Teilzeit arbeitet, dann ___ sie nicht den ganzen Tag am Computer sitzen.","gaps":[["muss"]],"solution":"Wenn sie nur Teilzeit arbeitet, dann **muss** sie nicht den ganzen Tag am Computer sitzen.","en":"Se lavora solo a tempo parziale, non deve stare seduta al computer tutto il giorno.","why":"L'infinito *sitzen* non ha *zu*, quindi il verbo è *müssen*: *sie muss … sitzen*.","source":"g98"},{"label":"d","text":"Wenn wir für drei Monate ins Ausland reisen wollen, dann ___ wir jetzt viel Geld sparen.","gaps":[["müssen"]],"solution":"Wenn wir für drei Monate ins Ausland reisen wollen, dann **müssen** wir jetzt viel Geld sparen.","en":"Se vogliamo viaggiare all'estero per tre mesi, adesso dobbiamo risparmiare molti soldi.","why":"Niente *zu* e nessuna negazione: è un obbligo, quindi *müssen*.","source":"g98"}]},{"no":"8","tag":"A2","instruction":"Mein Traumjob. Schreiben Sie Sätze mit *brauchen … zu*.","instruction_en":"Il lavoro dei miei sogni. Scrivi frasi con *brauchen … zu* + infinito (= non dover / dover solo).","example":[{"label":"a","lead":"(nicht früh aufstehen)","text":"In meinem Traumjob **brauche ich nicht früh aufzustehen**."}],"items":[{"label":"b","lead":"(keine langweiligen Aufgaben übernehmen)","text":"","accept":["Ich brauche keine langweiligen Aufgaben zu übernehmen.","In meinem Traumjob brauche ich keine langweiligen Aufgaben zu übernehmen."],"solution":"**Ich brauche keine langweiligen Aufgaben zu übernehmen.**","en":"Non devo assumermi compiti noiosi.","why":"*brauchen* in seconda posizione, *zu übernehmen* alla fine. Qui *übernehmen* non è separabile, quindi *zu* sta davanti.","source":"g98"},{"label":"c","lead":"(keine Überstunden machen)","text":"","accept":["Ich brauche keine Überstunden zu machen.","In meinem Traumjob brauche ich keine Überstunden zu machen."],"solution":"**Ich brauche keine Überstunden zu machen.**","en":"Non devo fare straordinari.","why":"*keine* + *brauchen … zu* = nessun obbligo.","source":"g98"},{"label":"d","lead":"(nur arbeiten, wenn ich Lust dazu habe)","text":"","accept":["Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.","In meinem Traumjob brauche ich nur zu arbeiten, wenn ich Lust dazu habe."],"solution":"**Ich brauche nur zu arbeiten, wenn ich Lust dazu habe.**","en":"Devo lavorare solo quando ne ho voglia.","why":"*nur brauchen … zu* = dover solo. *zu arbeiten* chiude la frase principale prima della frase con *wenn*.","source":"g98"},{"label":"e","lead":"(nicht mit unfreundlichen Kollegen zusammenarbeiten)","text":"","accept":["Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.","In meinem Traumjob brauche ich nicht mit unfreundlichen Kollegen zusammenzuarbeiten."],"solution":"**Ich brauche nicht mit unfreundlichen Kollegen zusammenzuarbeiten.**","en":"Non devo lavorare con colleghi antipatici.","why":"*zusammenarbeiten* è separabile: *zusammen**zu**arbeiten*, una sola parola.","source":"g4069"}]},{"no":"9","tag":"A4","instruction":"Ein Bewerbungsschreiben","instruction_en":"Una lettera di candidatura","part":"a","part_instruction":"Lesen Sie und ordnen Sie.","part_instruction_en":"Leggi le parti della lettera e mettile nell'ordine giusto: scrivi il numero (1–8) di ogni parte. Qui le parti sono contrassegnate con le lettere A–H nell'ordine in cui le stampa il libro; B è l'esempio.","example":[{"label":"B","text":"Bewerbung als Verkäufer von E-Bikes → **1**"}],"items":[{"label":"A","text":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → ___","gaps":[["5"]],"solution":"Es fällt mir leicht, neue Dinge zu lernen. Ausserdem macht es mir Freude, Kunden zu beraten. Deshalb wäre ich gern als Verkäufer bei Ihnen tätig. → **5**","en":"Imparo facilmente cose nuove. Inoltre mi piace consigliare i clienti. Per questo mi piacerebbe lavorare come venditore nella Sua azienda. → 5","why":"Il motivo per cui vuoi il posto viene dopo la tua esperienza (4) e prima della richiesta finale (6).","source":"hueber"},{"label":"C","text":"Freundliche Grüsse / Tibor Kelemen → ___","gaps":[["7"]],"solution":"Freundliche Grüsse / Tibor Kelemen → **7**","en":"Cordiali saluti / Tibor Kelemen → 7","why":"Il saluto finale e il tuo nome vengono dopo l'ultima frase.","source":"hueber"},{"label":"D","text":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → ___","gaps":[["3"]],"solution":"Mit grossem Interesse habe ich Ihr Inserat gelesen und bewerbe mich um die freie Stelle als Verkäufer von E-Bikes. → **3**","en":"Ho letto con grande interesse il Suo annuncio e mi candido per il posto vacante di venditore di e-bike. → 3","why":"La prima frase dopo il saluto iniziale dice per quale posto ti candidi.","source":"hueber"},{"label":"E","text":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → ___","gaps":[["6"]],"solution":"Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. → **6**","en":"Sarei lieto di essere invitato a un colloquio personale. → 6","why":"La frase finale classica di una lettera di candidatura.","source":"hueber"},{"label":"F","text":"Beilagen: Lebenslauf, Arbeitszeugnisse → ___","gaps":[["8"]],"solution":"Beilagen: Lebenslauf, Arbeitszeugnisse → **8**","en":"Allegati: curriculum vitae, certificati di lavoro → 8","why":"Gli allegati (*Beilagen*) vengono proprio alla fine, sotto il nome.","source":"hueber"},{"label":"G","text":"Sehr geehrte Damen und Herren → ___","gaps":[["2"]],"solution":"Sehr geehrte Damen und Herren → **2**","en":"Gentili signore e signori → 2","why":"Il saluto iniziale segue la riga dell'oggetto. In Svizzera dopo il saluto non si mette la virgola.","source":"hueber"},{"label":"H","text":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → ___","gaps":[["4"]],"solution":"Wie Sie meinen Unterlagen entnehmen können, habe ich nach meinem Sekundarschulabschluss die Ausbildung zum Fahrradmechaniker bei der Firma «Velo-XL» gemacht. Danach war ich zwei Jahre als Angestellter in einem Velogeschäft tätig und konnte auch erste Erfahrungen im Verkauf sammeln. → **4**","en":"Come può vedere dai miei documenti, dopo il diploma di scuola secondaria ho fatto la formazione da meccanico di biciclette presso la ditta «Velo-XL». Poi ho lavorato per due anni come dipendente in un negozio di bici e ho potuto fare anche le prime esperienze nella vendita. → 4","why":"La tua formazione e la tua esperienza vengono dopo la frase d'apertura.","source":"hueber"}]}]},{"page":"AB 143","heading":"A  Fang endlich an, Bewerbungen zu schreiben!","heading_en":"Comincia finalmente a scrivere candidature!","exercises":[{"no":"9","part":"b","part_instruction":"Ergänzen Sie das Bewerbungsschreiben. Hilfe finden Sie in a.","part_instruction_en":"Completa la lettera di candidatura. Trovi un aiuto in a.","reading":[{"label":"Lerntipp","text":"Ein Bewerbungsschreiben muss fehlerfrei sein! Notieren Sie zuerst Ihre typischen Fehler. Überprüfen Sie dann Ihren Text pro Fehlertyp einmal. Lassen Sie Ihre Bewerbung am Ende noch einmal von einem Muttersprachler Korrektur lesen."}],"example":[{"label":"1","text":"Bewerbung **als** Physiotherapeutin im Altersheim"}],"items":[{"label":"2","text":"Sehr ___ Frau Zerlich","gaps":[["geehrte"]],"solution":"Sehr **geehrte** Frau Zerlich","en":"Gentile signora Zerlich","why":"*Sehr geehrte Frau …*, *Sehr geehrter Herr …*: la desinenza dipende dalla persona.","source":"hueber"},{"label":"3","text":"___ habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","gaps":[["Mit grossem Interesse"]],"solution":"**Mit grossem Interesse** habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Physiotherapeutin.","en":"Ho letto con grande interesse il Suo annuncio di lavoro e mi candido per il posto di fisioterapista.","why":"Frase d'apertura fissa di a; occupa la posizione 1, quindi segue il verbo *habe*.","source":"hueber"},{"label":"4","text":"Wie Sie ___ entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","gaps":[["meinen Unterlagen"]],"solution":"Wie Sie **meinen Unterlagen** entnehmen können, war ich in Polen nach meiner Ausbildung zur Physiotherapeutin vier Jahre in einem Spital in Lodz tätig.","en":"Come può vedere dai miei documenti, in Polonia, dopo la mia formazione da fisioterapista, ho lavorato quattro anni in un ospedale di Lodz.","why":"*etwas (Dativ) entnehmen* = ricavare da qualcosa: *meinen Unterlagen* è dativo plurale.","source":"hueber"},{"label":"5","text":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch ___ im Bereich der Sportmedizin sammeln.","gaps":[["Erfahrungen","erste Erfahrungen"]],"solution":"Danach habe ich zwei Jahre in der Praxis *Kunz & Rosenthal* gearbeitet. Dort konnte ich auch **Erfahrungen** im Bereich der Sportmedizin sammeln.","en":"Poi ho lavorato due anni nello studio Kunz & Rosenthal. Lì ho potuto fare esperienza anche nel campo della medicina dello sport.","why":"*Erfahrungen sammeln* = fare esperienza.","source":"hueber"},{"label":"6","text":"___ ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","gaps":[["Meine Muttersprache"]],"solution":"**Meine Muttersprache** ist Polnisch. Ich spreche aber auch sehr gut Deutsch und Englisch.","en":"La mia lingua madre è il polacco. Ma parlo anche molto bene tedesco e inglese.","why":"*die Muttersprache* = lingua madre; *meine* perché è femminile.","source":"hueber"},{"label":"7","text":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es ___ grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","gaps":[["macht mir"]],"solution":"Die Stelle in einem Altersheim ist für mich etwas ganz Neues. Es **macht mir** grosse Freude, Neues zu lernen. Ausserdem kümmere ich mich gern um andere Menschen und freue mich auf den Kontakt mit den Bewohnern.","en":"Il posto in una casa per anziani è per me qualcosa di completamente nuovo. Mi fa molto piacere imparare cose nuove. Inoltre mi prendo volentieri cura degli altri e non vedo l'ora di entrare in contatto con i residenti.","why":"*Es macht mir Freude, … zu* + infinito, come in a.","source":"hueber"},{"label":"8","text":"Über eine Einladung ___ würde ich mich freuen.","gaps":[["zu einem persönlichen Gespräch"]],"solution":"Über eine Einladung **zu einem persönlichen Gespräch** würde ich mich freuen.","en":"Sarei lieta di essere invitata a un colloquio personale.","why":"Frase finale fissa: *eine Einladung zu* + dativo.","source":"hueber"},{"label":"9","text":"___ Alina Jankowska","gaps":[["Freundliche Grüsse"]],"solution":"**Freundliche Grüsse** Alina Jankowska","en":"Cordiali saluti, Alina Jankowska","why":"Saluto finale; ortografia svizzera *Grüsse*.","source":"hueber"}]},{"no":"9","part":"c","part_instruction":"Wählen Sie ein Stelleninserat und schreiben Sie eine Bewerbung.","part_instruction_en":"Scegli uno dei tre annunci di lavoro dello Zirkus Tortellini e scrivi una lettera di candidatura. Usa le parti di a e b. La risposta modello è una possibilità.","reading":[{"label":"1","text":"Zirkus Tortellini sucht Dompteur/-in\nWir erwarten: + Ausbildung als Tierpfleger/-in + Erfahrung mit wilden Tieren (Tiger, …)\nInfos und Bewerbung bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"2","text":"Sind Sie ein fröhlicher, positiver Mensch? Dann arbeiten Sie bei uns als Clown/-in\nSie haben Berufserfahrung als Kleinkinderzieher/-in oder als Schauspieler/-in? Sie können gut mit Kindern umgehen und haben viele lustige Ideen? Dann sind Sie die Richtige oder der Richtige für uns!\nGleich bewerben bei Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"},{"label":"3","text":"Wir suchen zwei Artisten für unseren Zirkus.\nSie haben: + eine Ausbildung als Tänzer/-in + erste Berufserfahrung an einem Theater gesammelt oder schon als Artist/-in in einem Zirkus gearbeitet\nSenden Sie Ihre Bewerbung an Zirkusdirektor Flavio Tortellini: flavio.tortellini@zirkus-tortellini.com"}],"example":[{"label":"Beispiel","text":"Sehr geehrter Herr Tortellini / Mit grossem Interesse …"}],"items":[{"label":"1","lead":"Inserat 3: Artist/-in","text":"","open":true,"solution":"Bewerbung als Artistin / Sehr geehrter Herr Tortellini / Mit grossem Interesse habe ich Ihr Stelleninserat gelesen und bewerbe mich um die Stelle als Artistin in Ihrem Zirkus. Wie Sie meinen Unterlagen entnehmen können, habe ich eine Ausbildung als Tänzerin gemacht. Danach habe ich drei Jahre an einem Theater in Bern getanzt und dort erste Erfahrungen auf der Bühne gesammelt. Es macht mir grosse Freude, vor Publikum aufzutreten. Ich kann mir gut vorstellen, mit Ihrem Zirkus durch die Schweiz zu reisen. Über eine Einladung zu einem persönlichen Gespräch würde ich mich freuen. / Freundliche Grüsse / Lara Steiner / Beilagen: Lebenslauf, Arbeitszeugnis","en":"Candidatura come acrobata / Egregio signor Tortellini / Ho letto con grande interesse il Suo annuncio di lavoro e mi candido per il posto di acrobata nel Suo circo. Come può vedere dai miei documenti, ho fatto una formazione da ballerina. Poi ho ballato per tre anni in un teatro di Berna e lì ho fatto le prime esperienze sul palco. Mi fa molto piacere esibirmi davanti al pubblico. Riesco benissimo a immaginarmi di viaggiare per la Svizzera con il Suo circo. Sarei lieta di essere invitata a un colloquio personale. / Cordiali saluti / Lara Steiner / Allegati: curriculum vitae, certificato di lavoro","why":"Le stesse otto parti di a; ognuna risponde a un punto dell'annuncio (formazione da ballerina, prime esperienze in un teatro). *auf**zu**treten*: *auftreten* è separabile.","source":"g4069"}]}]},{"page":"AB 144","heading":"B  Während seines letzten Schuljahres …","heading_en":"Durante il suo ultimo anno di scuola …","exercises":[{"no":"10","tag":"B1","instruction":"Ergänzen Sie in der richtigen Form: *während – innerhalb – ausserhalb*.","instruction_en":"Completa con *während* (durante), *innerhalb* (entro) o *ausserhalb* (fuori da), più la parola tra parentesi nella forma giusta. Tutte e tre reggono il genitivo.","example":[{"label":"a","text":"Man sollte schon **während der** (die) Schulzeit Schnupperlehren machen."}],"items":[{"label":"b","lead":"(wenige)","text":"Vielen Dank für Ihre Bewerbung. Sie erhalten ___ Wochen unsere Antwort.","gaps":[["innerhalb weniger"]],"solution":"Vielen Dank für Ihre Bewerbung. Sie erhalten **innerhalb weniger** Wochen unsere Antwort.","en":"Grazie mille per la Sua candidatura. Riceverà la nostra risposta entro poche settimane.","why":"Un limite di tempo = *innerhalb*; genitivo plurale senza articolo: *weniger Wochen*.","source":"prep"},{"label":"c","lead":"(unsere)","text":"Sie rufen ___ Geschäftszeiten an. Diese sind von …","gaps":[["ausserhalb unserer"]],"solution":"Sie rufen **ausserhalb unserer** Geschäftszeiten an. Diese sind von …","en":"Sta chiamando fuori dai nostri orari di apertura. Sono dalle …","why":"Fuori da un periodo di tempo = *ausserhalb*; genitivo plurale *unserer Geschäftszeiten*.","source":"prep"},{"label":"d","lead":"(die)","text":"Sie können sich ___ Wartezeit gern einen Kaffee nehmen.","gaps":[["während der"]],"solution":"Sie können sich **während der** Wartezeit gern einen Kaffee nehmen.","en":"Durante l'attesa si serva pure di un caffè.","why":"Nello stesso momento di = *während*; genitivo femminile *der Wartezeit*.","source":"g299310"},{"label":"e","lead":"(die)","text":"Die Firma möchte ihre Ergebnisse ___ nächsten zwei Jahre um 20 % verbessern.","gaps":[["innerhalb der"]],"solution":"Die Firma möchte ihre Ergebnisse **innerhalb der** nächsten zwei Jahre um 20 % verbessern.","en":"L'azienda vuole migliorare i suoi risultati del 20 % entro i prossimi due anni.","why":"Un limite di tempo = *innerhalb*; genitivo plurale *der nächsten zwei Jahre*.","source":"prep"}]},{"no":"11","tag":"B2","instruction":"Ordnen Sie zu.","instruction_en":"Completa l'intervista con le preposizioni di tempo del riquadro. Ognuna si usa una volta; *während* è nel riquadro due volte. Il *von … an* barrato è usato nell'esempio.","phrases":["ausserhalb","bei","von … bis","nach","von … an (Beispiel)","Vor","während","während"],"reading":[{"label":"Karrierestart","text":"Technikerin HF Maschinenbau – ein Beruf auch für Mädchen? Interview mit Samira\nKarrierestart: Warum machst du eine Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie lange dauert die Ausbildung zur Maschinenbau-Technikerin?\nKarrierestart: Wie sieht dein Arbeitstag aus?\nKarrierestart: Welche Erfahrungen hast du als Frau … deiner Arbeit gemacht?"}],"example":[{"label":"d","text":"Ich durfte **von** Anfang **an** selbstständig Probleme lösen."}],"items":[{"label":"a","text":"Technik hat mich schon immer interessiert. Schon ___ meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","gaps":[["während"]],"solution":"Technik hat mich schon immer interessiert. Schon **während** meiner Schulzeit habe ich bei einem Elektroinstallateur gearbeitet.","en":"La tecnica mi ha sempre interessato. Già durante gli anni di scuola ho lavorato presso un elettricista.","why":"*während* + genitivo (*meiner Schulzeit*) = durante.","source":"g299310"},{"label":"b","text":"Gleich ___ der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","gaps":[["nach"]],"solution":"Gleich **nach** der Schule habe ich ein Praktikum bei einem grossen Energieunternehmen gemacht.","en":"Subito dopo la scuola ho fatto uno stage presso una grande azienda energetica.","why":"*nach* + dativo (*der Schule*) = dopo.","source":"prep"},{"label":"c","text":"Aber schon ___ des ersten Jahres lernt man die wichtigsten Dinge kennen.","gaps":[["während"]],"solution":"Aber schon **während** des ersten Jahres lernt man die wichtigsten Dinge kennen.","en":"Ma già durante il primo anno si imparano le cose più importanti.","why":"*während* + genitivo *des ersten Jahres*.","source":"g299310"},{"label":"e","text":"___ der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","gaps":[["Vor"]],"solution":"**Vor** der Abschlussprüfung muss ich aber trotzdem noch viel lernen.","en":"Prima dell'esame finale devo comunque studiare ancora molto.","why":"*vor* + dativo (*der Abschlussprüfung*) = prima di; maiuscola all'inizio della frase.","source":"prep"},{"label":"f","text":"Ich bin ___ morgens ___ zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","gaps":[["von"],["bis"]],"solution":"Ich bin **von** morgens **bis** zum Feierabend auf dem Gebiet unseres Unternehmens unterwegs und repariere Anlagen.","en":"Dalla mattina fino alla fine della giornata lavorativa giro per l'area della nostra azienda e riparo impianti.","why":"*von … bis* = da … fino a; *bis zum Feierabend* (*zum* = *zu dem*).","source":"prep"},{"label":"g","text":"Welche Erfahrungen hast du als Frau ___ deiner Arbeit gemacht?","gaps":[["bei"]],"solution":"Welche Erfahrungen hast du als Frau **bei** deiner Arbeit gemacht?","en":"Che esperienze hai fatto come donna nel tuo lavoro?","why":"*bei* + dativo (*deiner Arbeit*) = nel corso di, durante.","source":"prep"},{"label":"h","text":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also ___ der Arbeitszeit.","gaps":[["ausserhalb"]],"solution":"Nur positive! Meine Kollegen und ich treffen uns oft abends, also **ausserhalb** der Arbeitszeit.","en":"Solo positive! I miei colleghi e io ci troviamo spesso la sera, quindi fuori dall'orario di lavoro.","why":"*ausserhalb* + genitivo (*der Arbeitszeit*) = fuori da.","source":"prep"}]},{"no":"12","tag":"B2","instruction":"Lesen Sie den Text und schliessen Sie die Lücken 1–6. Welche Lösung (a, b oder c) passt am besten?","instruction_en":"Preparazione all'esame: leggi l'e-mail e completa gli spazi 1–6. Quale opzione (a, b o c) è la più adatta? Scrivi la parola (o la sua lettera).","reading":[{"label":"E-Mail senden","text":"Sehr (0) Herr Nemati\nVielen Dank (1) Ihre Bewerbung als Automobil-Mechatroniker. Wir freuen uns über Ihr (2) an unserer Firma und laden Sie zu einem Vorstellungsgespräch am 25. Mai um 11.30 Uhr ein. Bitte geben Sie uns (3) der nächsten Tage Bescheid, (4) Sie zu diesem Termin kommen können. Bringen Sie noch folgende (5) mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat. Für Fragen und weitere Informationen (6) wir Ihnen gern zur Verfügung.\nFreundliche Grüsse\nFranziska Leumann – Garage Leumann"}],"example":[{"label":"0","lead":"a geehrter · b lieber · c freundlicher","text":"Sehr **geehrter** Herr Nemati"}],"items":[{"label":"1","lead":"a um · b für · c bei","text":"Vielen Dank ___ Ihre Bewerbung als Automobil-Mechatroniker.","gaps":[["für","b","b für"]],"solution":"Vielen Dank **für** Ihre Bewerbung als Automobil-Mechatroniker.","en":"Grazie mille per la Sua candidatura come meccatronico d'automobili.","why":"*Vielen Dank für* + accusativo.","source":"hueber"},{"label":"2","lead":"a Bewerbung · b Interesse · c Mitarbeit","text":"Wir freuen uns über Ihr ___ an unserer Firma …","gaps":[["Interesse","b","b Interesse"]],"solution":"Wir freuen uns über Ihr **Interesse** an unserer Firma …","en":"Siamo lieti del Suo interesse per la nostra azienda …","why":"*Interesse an* + dativo = interesse per; *Ihr* si accorda con il neutro *das Interesse*.","source":"hueber"},{"label":"3","lead":"a innerhalb · b ausserhalb · c bis","text":"Bitte geben Sie uns ___ der nächsten Tage Bescheid, …","gaps":[["innerhalb","a","a innerhalb"]],"solution":"Bitte geben Sie uns **innerhalb** der nächsten Tage Bescheid, …","en":"Ci faccia sapere entro i prossimi giorni …","why":"Un limite di tempo con il genitivo (*der nächsten Tage*) = *innerhalb*. *bis* richiederebbe *bis zum …*.","source":"prep"},{"label":"4","lead":"a wenn · b wann · c ob","text":"…, ___ Sie zu diesem Termin kommen können.","gaps":[["ob","c","c ob"]],"solution":"…, **ob** Sie zu diesem Termin kommen können.","en":"… se può venire a questo appuntamento.","why":"Una domanda indiretta sì/no richiede *ob* (se).","source":"hueber"},{"label":"5","lead":"a Zeugnisse · b Sachen · c Dokumente","text":"Bringen Sie noch folgende ___ mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","gaps":[["Dokumente","c","c Dokumente"]],"solution":"Bringen Sie noch folgende **Dokumente** mit: den Berufsschulabschluss im Original und Ihr B2-Zertifikat.","en":"Porti anche i seguenti documenti: il diploma della scuola professionale in originale e il Suo certificato B2.","why":"Un certificato e un diploma sono *Dokumente*; *Zeugnisse* non comprenderebbe anche il certificato B2, e *Sachen* è troppo vago per una lettera formale.","source":"hueber"},{"label":"6","lead":"a stellen · b stehen · c haben","text":"Für Fragen und weitere Informationen ___ wir Ihnen gern zur Verfügung.","gaps":[["stehen","b","b stehen"]],"solution":"Für Fragen und weitere Informationen **stehen** wir Ihnen gern zur Verfügung.","en":"Restiamo volentieri a Sua disposizione per domande e ulteriori informazioni.","why":"Espressione fissa: *jemandem zur Verfügung stehen* = essere a disposizione di qualcuno.","source":"hueber"}]}]},{"page":"AB 145","heading":"B  Während seines letzten Schuljahres …","heading_en":"Durante il suo ultimo anno di scuola …","exercises":[{"no":"14","tag":"B3","instruction":"Verbinden Sie.","instruction_en":"Abbina ogni domanda od osservazione di un colloquio di lavoro alla risposta giusta (1–7). Scrivi il numero. (L'esercizio 13 è un ascolto ed è omesso.)","phrases":["1 Ich war zuständig für die Kontrolle von Haushalts-, Garten- und Freizeitartikeln.","2 Ich beherrsche die üblichen Programme und habe mich letztes Jahr im Bereich Lagerdatenbank weitergebildet.","3 Ja, ich würde gern wissen, wie gross das Lager hier ist.","4 Vielen Dank auch Ihnen.","5 Vielen Dank.","6 Ja, ich spreche drei Sprachen.","7 Also, ich bin Baumaschinenmechaniker und mache gerade den Führerausweis Kategorie BE."],"example":[{"label":"a","text":"Guten Tag, Herr Trantow. Nehmen Sie doch bitte Platz. → **5** Vielen Dank."}],"items":[{"label":"b","text":"Erzählen Sie doch bitte etwas über sich. → ___","gaps":[["7"]],"solution":"Erzählen Sie doch bitte etwas über sich. → **7**","en":"Mi racconti qualcosa di sé, per favore. → 7 Allora, sono meccanico di macchine edili e sto prendendo la patente di categoria BE.","why":"Ti presenti: il tuo lavoro e che cosa stai facendo adesso.","source":"hueber"},{"label":"c","text":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → ___","gaps":[["1"]],"solution":"Welche Aufgaben hatten Sie bei Ihrem letzten Arbeitgeber? → **1**","en":"Quali compiti aveva presso il Suo ultimo datore di lavoro? → 1 Ero responsabile del controllo degli articoli per la casa, il giardino e il tempo libero.","why":"*zuständig sein für* = essere responsabile di (i tuoi compiti).","source":"hueber"},{"label":"d","text":"Haben Sie noch andere Fähigkeiten? → ___","gaps":[["6"]],"solution":"Haben Sie noch andere Fähigkeiten? → **6**","en":"Ha anche altre competenze? → 6 Sì, parlo tre lingue.","why":"Una domanda sì/no sulle competenze: *Ja, …*","source":"hueber"},{"label":"e","text":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → ___","gaps":[["2"]],"solution":"Können Sie mir mehr über Ihre Computerkenntnisse erzählen? → **2**","en":"Può dirmi di più sulle Sue conoscenze informatiche? → 2 Conosco i programmi più comuni e l'anno scorso ho fatto una formazione continua sui database di magazzino.","why":"*beherrschen* = padroneggiare; *sich weiterbilden* = fare una formazione continua.","source":"hueber"},{"label":"f","text":"Haben Sie noch eine Frage? → ___","gaps":[["3"]],"solution":"Haben Sie noch eine Frage? → **3**","en":"Ha ancora qualche domanda? → 3 Sì, vorrei sapere quanto è grande il magazzino qui.","why":"Una domanda indiretta: *wie gross das Lager hier ist* (verbo alla fine).","source":"hueber"},{"label":"g","text":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → ___","gaps":[["4"]],"solution":"Vielen Dank, dass Sie zu uns gekommen sind, Herr Trantow. → **4**","en":"Grazie mille di essere venuto da noi, signor Trantow. → 4 Grazie anche a Lei.","why":"Ricambi il ringraziamento: *Vielen Dank auch Ihnen.*","source":"hueber"}]},{"no":"15","tag":"B3","instruction":"Das kann ich! Ergänzen Sie Informationen über sich.","instruction_en":"Lo so fare! Completa le frasi con informazioni su di te. Le risposte modello sono una possibilità.","items":[{"label":"a","lead":"Ich habe schon während der Schulzeit/des Studiums …","text":"","open":true,"solution":"Ich habe schon während der Schulzeit in einem Café gejobbt.","en":"Già durante gli anni di scuola facevo un lavoretto in un caffè.","why":"*während* + genitivo; Perfekt con il participio alla fine.","source":"g299310"},{"label":"b","lead":"Ich bin/war zuständig für …","text":"","open":true,"solution":"Ich war zuständig für die Buchhaltung in einem kleinen Büro.","en":"Ero responsabile della contabilità in un piccolo ufficio.","why":"*zuständig für* + accusativo.","source":"hueber"},{"label":"c","lead":"Ich beherrsche …","text":"","open":true,"solution":"Ich beherrsche Excel und die üblichen Office-Programme.","en":"Padroneggio Excel e i comuni programmi da ufficio.","why":"*beherrschen* + accusativo = padroneggiare una competenza o una lingua.","source":"hueber"},{"label":"d","lead":"Ich habe auch (sehr) gute Kenntnisse in …","text":"","open":true,"solution":"Ich habe auch sehr gute Kenntnisse in Englisch und Italienisch.","en":"Ho anche ottime conoscenze di inglese e italiano.","why":"*Kenntnisse in* + dativo.","source":"hueber"},{"label":"e","lead":"Es fällt mir leicht, …","text":"","open":true,"solution":"Es fällt mir leicht, im Team zu arbeiten und auf neue Kunden zuzugehen.","en":"Mi riesce facile lavorare in team e avvicinare nuovi clienti.","why":"*Es fällt mir leicht* + *zu* + infinito; *zugehen* è separabile: *zu**zu**gehen*.","source":"g4069"}]}]},{"page":"AB 146","heading":"C  Berufsberatung","heading_en":"Orientamento professionale","exercises":[{"no":"16","tag":"C2","instruction":"Was ist richtig? Lesen Sie und kreuzen Sie an.","instruction_en":"Che cosa è giusto? Leggi i testi. Scrivi *richtig* (giusto) o *falsch* (sbagliato) dopo ogni frase; nel libro segni solo quelle giuste.","reading":[{"label":"Was wollt ihr werden? – Jacqueline","text":"Ich gehe noch zur Schule. Nächstes Jahr mache ich die Matura. Ein Studium ist aber nichts für mich. Das dauert zu lange. Planung und Organisation sind kein Problem für mich. Deshalb möchte ich einen kaufmännischen Beruf ergreifen. Kommenden Montag habe ich einen Termin bei der Berufsberatung."},{"label":"Konstantinos","text":"In der Schule war ich gut in Mathematik und Kunst. Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte. Und ich wollte auch künstlerisch tätig sein. Aber ich wusste nicht, wie ich das zusammenbringen sollte. Deshalb bin ich zur Berufsberatung gegangen. Der Berater hat mir eine Lehre als Zeichner Landschaftsarchitektur empfohlen. Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt."}],"items":[{"label":"a","text":"Jacqueline hat keine Lust zu studieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Jacqueline hat keine Lust zu studieren. → **richtig**","en":"Jacqueline non ha voglia di studiare all'università. → giusto","why":"*Ein Studium ist aber nichts für mich. Das dauert zu lange.*","source":"hueber"},{"label":"b","text":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → ___","gaps":[["falsch","f","nein"]],"solution":"Sie findet es schwierig, etwas zu planen oder zu organisieren. → **falsch**","en":"Trova difficile pianificare o organizzare qualcosa. → sbagliato","why":"Il contrario: *Planung und Organisation sind kein Problem für mich.*","source":"hueber"},{"label":"c","text":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → ___","gaps":[["richtig","r","ja"]],"solution":"Nächste Woche will sie sich über kaufmännische Ausbildungen informieren. → **richtig**","en":"La settimana prossima vuole informarsi sulle formazioni commerciali. → giusto","why":"*Kommenden Montag habe ich einen Termin bei der Berufsberatung*, per un lavoro commerciale.","source":"hueber"},{"label":"d","text":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → ___","gaps":[["richtig","r","ja"]],"solution":"Konstantinos hatte vor, nach der Schule im Bereich Technik zu arbeiten. → **richtig**","en":"Konstantinos aveva intenzione di lavorare nel campo della tecnica dopo la scuola. → giusto","why":"*Für mich war immer klar, dass ich mich mit technischen Fragen beschäftigen möchte.*","source":"hueber"},{"label":"e","text":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → ___","gaps":[["richtig","r","ja"]],"solution":"Er fand es zunächst schwierig, seine Interessensgebiete zu verbinden. → **richtig**","en":"All'inizio trovava difficile conciliare i suoi campi di interesse. → giusto","why":"*Aber ich wusste nicht, wie ich das zusammenbringen sollte.*","source":"hueber"},{"label":"f","text":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → ___","gaps":[["falsch","f","nein"]],"solution":"Er hat erwartet, dass ihm die Lehre als Zeichner Landschaftsarchitektur Freude macht. → **falsch**","en":"Si aspettava che l'apprendistato come disegnatore in architettura del paesaggio gli sarebbe piaciuto. → sbagliato","why":"*Ich hätte nicht gedacht, dass mir diese Arbeit so gut gefällt* = non se lo aspettava.","source":"hueber"}]},{"no":"17","tag":"C2","instruction":"Schreiben Sie Sätze (a–e). Ordnen Sie dann den passenden Ratschlag (1–5) zu.","instruction_en":"Scrivi una frase con *zu* + infinito per ogni spunto (a–e). Poi trova il consiglio adatto (1–5); la soluzione indica il suo numero.","phrases":["1 Du könntest Busfahrer werden.","2 Dann werde doch Schreiner.","3 Hm, schwierig. Vielleicht Modedesigner?","4 Wie wäre es mit einer Tätigkeit als Bäcker?","5 An deiner Stelle würde ich Köchin werden."],"example":[{"label":"a","lead":"sich gut vorstellen können – im handwerklichen Bereich arbeiten","text":"**Ich kann mir gut vorstellen, im handwerklichen Bereich zu arbeiten.** → 2"}],"items":[{"label":"b","lead":"es nicht schwer finden – früh aufstehen","text":"","accept":["Ich finde es nicht schwer, früh aufzustehen.","Es fällt mir nicht schwer, früh aufzustehen."],"solution":"**Ich finde es nicht schwer, früh aufzustehen.** → 4","en":"Non trovo difficile alzarmi presto. → 4 Che ne dici di un lavoro come panettiere?","why":"*Ich finde es* + aggettivo + *zu* + infinito; *aufstehen* è separabile: *auf**zu**stehen*. I panettieri cominciano a lavorare molto presto.","source":"g4069","check":"La soluzione ufficiale scrive *Es fällt mir nicht schwer, früh aufzustehen*, che significa la stessa cosa; lo spunto *es nicht schwer finden* dà *Ich finde es nicht schwer, …*. Entrambe sono corrette."},{"label":"c","lead":"Lust haben – viel unterwegs sein","text":"","accept":["Ich habe Lust, viel unterwegs zu sein."],"solution":"**Ich habe Lust, viel unterwegs zu sein.** → 1","en":"Ho voglia di essere spesso in giro. → 1 Potresti diventare autista di autobus.","why":"*Lust haben* + *zu* + infinito.","source":"g6865"},{"label":"d","lead":"Freude machen – für andere kochen","text":"","accept":["Es macht mir Freude, für andere zu kochen.","Mir macht es Freude, für andere zu kochen."],"solution":"**Es macht mir Freude, für andere zu kochen.** → 5","en":"Mi piace cucinare per gli altri. → 5 Se fossi in te, diventerei cuoco.","why":"*Es macht mir Freude* + *zu* + infinito.","source":"g6865"},{"label":"e","lead":"Interesse haben – Neues entwickeln","text":"","accept":["Ich habe Interesse daran, Neues zu entwickeln.","Ich habe Interesse, Neues zu entwickeln."],"solution":"**Ich habe Interesse daran, Neues zu entwickeln.** → 3","en":"Mi interessa sviluppare cose nuove. → 3 Mmh, difficile. Forse stilista?","why":"*Interesse haben (daran)* + *zu* + infinito; *daran* rimanda alla frase con *zu* che segue.","source":"g6865"}]},{"no":"18","tag":"C2","instruction":"Wörter mit -ng","instruction_en":"Parole con -ng","part":"a","part_instruction":"Bilden Sie Wörter mit *-ung*.","part_instruction_en":"Forma dei sostantivi in *-ung* a partire dai verbi, con l'articolo. (Le parti b–d sono ascolti e sono omesse.)","example":[{"label":"1","text":"beraten → **die Beratung**"},{"label":"4","text":"entwickeln → **die Entwicklung**"}],"items":[{"label":"2","text":"erfahren → ___","gaps":[["die Erfahrung","Erfahrung"]],"solution":"erfahren → **die Erfahrung**","en":"sperimentare → esperienza","why":"Radice del verbo + *-ung*; i sostantivi in *-ung* sono sempre femminili: *die*.","source":"hueber"},{"label":"3","text":"verantworten → ___","gaps":[["die Verantwortung","Verantwortung"]],"solution":"verantworten → **die Verantwortung**","en":"essere responsabile di → responsabilità","why":"Radice *verantwort-* + *-ung*: *die Verantwortung*.","source":"hueber"},{"label":"5","text":"beschäftigen → ___","gaps":[["die Beschäftigung","Beschäftigung"]],"solution":"beschäftigen → **die Beschäftigung**","en":"occupare / impiegare → impiego, occupazione","why":"Radice *beschäftig-* + *-ung*.","source":"hueber"},{"label":"6","text":"unterstützen → ___","gaps":[["die Unterstützung","Unterstützung"]],"solution":"unterstützen → **die Unterstützung**","en":"sostenere → sostegno","why":"Radice *unterstütz-* + *-ung*.","source":"hueber"}]}]},{"page":"AB 147","heading":"D  Small Talk: Von der Arbeit erzählen","heading_en":"Small talk: parlare di lavoro","exercises":[{"no":"19","tag":"D2","instruction":"Ordnen Sie zu.","instruction_en":"Completa il dialogo di small talk tra Bettina (○) e un amico (◆) con le espressioni dei due riquadri (qui riunite in uno solo). Ogni espressione si usa una volta; quella barrata è usata nell'esempio.","box":["es ist total stressig","Hast du noch nie daran gedacht","muss zwei Kollegen vertreten","Hast du immer noch so viel Arbeit","schon mehrere Bewerbungen geschrieben","suche immer noch eine Stelle","Wie läuft's denn so","Ist das nicht anstrengend","machst du jetzt eigentlich genau","habe kein Interesse","komme gut mit den Kunden und den Kollegen zurecht","muss jetzt leider gehen"],"box_used":[6],"box_exact":true,"example":[{"label":"a","text":"◆ Hoi, Bettina. Das ist aber schön, dich zu sehen. **Wie läuft's denn so** mit der Jobsuche?"}],"items":[{"label":"b","text":"○ Schwierig. Ich ___ als Übersetzerin.","gaps":[["suche immer noch eine Stelle"]],"solution":"○ Schwierig. Ich **suche immer noch eine Stelle** als Übersetzerin.","en":"○ Difficile. Sto ancora cercando un posto come traduttrice.","why":"Dopo *Ich* segue il verbo *suche*.","source":"hueber"},{"label":"c","text":"○ Ich habe ___, aber nur Absagen erhalten.","gaps":[["schon mehrere Bewerbungen geschrieben"]],"solution":"○ Ich habe **schon mehrere Bewerbungen geschrieben**, aber nur Absagen erhalten.","en":"○ Ho già scritto diverse candidature, ma ho ricevuto solo risposte negative.","why":"Perfekt: *habe … geschrieben*, in parallelo con *erhalten*.","source":"hueber"},{"label":"d","text":"◆ ___, dich selbstständig zu machen? Das machen doch viele Übersetzer.","gaps":[["Hast du noch nie daran gedacht"]],"solution":"◆ **Hast du noch nie daran gedacht**, dich selbstständig zu machen? Das machen doch viele Übersetzer.","en":"◆ Non hai mai pensato di metterti in proprio? Lo fanno molti traduttori.","why":"*daran denken* + *zu* + infinito; *daran* rimanda alla frase con *zu*.","source":"hueber"},{"label":"e","text":"○ Ja, das stimmt. Aber ___, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","gaps":[["es ist total stressig"]],"solution":"○ Ja, das stimmt. Aber **es ist total stressig**, immer nach Aufträgen zu suchen. Ausserdem gibt es viel Konkurrenz.","en":"○ Sì, è vero. Ma è davvero stressante cercare sempre incarichi. E poi c'è molta concorrenza.","why":"*Es ist* + aggettivo + *zu* + infinito.","source":"hueber"},{"label":"f","text":"○ Aber wie geht es dir denn? ___?","gaps":[["Hast du immer noch so viel Arbeit"]],"solution":"○ Aber wie geht es dir denn? **Hast du immer noch so viel Arbeit**?","en":"○ Ma tu come stai? Hai ancora così tanto lavoro?","why":"La risposta *Ja, leider* richiede una domanda sì/no.","source":"hueber"},{"label":"g","text":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich ___. Und das jetzt, wo wir so viele Aufträge haben!","gaps":[["muss zwei Kollegen vertreten"]],"solution":"◆ Ja, leider. Bei uns in der Firma sind im Moment mehrere Leute krank. Ich **muss zwei Kollegen vertreten**. Und das jetzt, wo wir so viele Aufträge haben!","en":"◆ Sì, purtroppo. Nella nostra ditta al momento diverse persone sono malate. Devo sostituire due colleghi. E proprio adesso che abbiamo così tanti ordini!","why":"*vertreten* = sostituire qualcuno.","source":"hueber"},{"label":"h","text":"○ Was ___?","gaps":[["machst du jetzt eigentlich genau"]],"solution":"○ Was **machst du jetzt eigentlich genau**?","en":"○ Ma tu che cosa fai esattamente adesso?","why":"Una domanda con parola interrogativa: *Was* + verbo *machst* + *du*.","source":"hueber"},{"label":"i","lead":"◆ Ich bin als Heizungsinstallateur tätig. Ich habe die Verantwortung für zwei Baustellen und soll nebenbei die Baustellen meiner Kollegen betreuen.","text":"○ ___, immer von Baustelle zu Baustelle zu fahren?","gaps":[["Ist das nicht anstrengend"]],"solution":"○ **Ist das nicht anstrengend**, immer von Baustelle zu Baustelle zu fahren?","en":"○ Non è faticoso andare sempre da un cantiere all'altro?","why":"*Ist das nicht anstrengend, … zu* + infinito?","source":"hueber"},{"label":"j","text":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich ___. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","gaps":[["komme gut mit den Kunden und den Kollegen zurecht"]],"solution":"◆ Manchmal schon, aber meistens macht mir die Arbeit Freude. Ich **komme gut mit den Kunden und den Kollegen zurecht**. Übrigens, meine Firma sucht gerade jemanden fürs Büro. Willst du dich nicht bewerben?","en":"◆ A volte sì, ma per lo più il lavoro mi piace. Vado d'accordo con i clienti e con i colleghi. A proposito, la mia ditta sta cercando qualcuno per l'ufficio. Non vuoi candidarti?","why":"*mit jemandem gut zurechtkommen* = andare d'accordo con qualcuno (separabile).","source":"hueber"},{"label":"k","text":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich ___ an einer Tätigkeit als Sekretärin.","gaps":[["habe kein Interesse"]],"solution":"○ Aber was meinst denn du! Ich bin Übersetzerin. Ich **habe kein Interesse** an einer Tätigkeit als Sekretärin.","en":"○ Ma che dici! Sono traduttrice. Non mi interessa un lavoro come segretaria.","why":"*Interesse an* + dativo (*an einer Tätigkeit*).","source":"hueber"},{"label":"l","lead":"◆ Warum nicht? Als Übersetzerin sitzt du doch auch am Computer, schreibst und telefonierst. Der Job ist sicher und unsere Firma zahlt nicht schlecht. Überleg es dir doch einmal.","text":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich ___.","gaps":[["muss jetzt leider gehen"]],"solution":"○ Okay, das mache ich. Danke für den Tipp. Oh, ich **muss jetzt leider gehen**.","en":"○ Va bene, lo faccio. Grazie del consiglio. Oh, purtroppo adesso devo andare.","why":"Un modo tipico per chiudere uno small talk.","source":"hueber"}]},{"no":"20","tag":"D2","instruction":"Ergänzen Sie.","instruction_en":"Completa i brevi annunci. Il libro dà alcune lettere di ogni parola; scrivi la parola intera.","example":[{"label":"Beispiel","text":"In den Semesterferien **jobben** – …"}],"items":[{"label":"A","lead":"Ü _ _ _ s _ tz _ _ /in","text":"In den Semesterferien jobben – wir suchen dich als ___/in von kurzen Werbetexten.","gaps":[["Übersetzer"]],"solution":"In den Semesterferien jobben – wir suchen dich als **Übersetzer**/in von kurzen Werbetexten.","en":"Lavoretti durante le vacanze semestrali: cerchiamo te come traduttore/traduttrice di brevi testi pubblicitari.","why":"*der Übersetzer / die Übersetzerin* = traduttore, traduttrice.","source":"hueber"},{"label":"B","lead":"A _ f _ _ ä _ _ n","text":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach ___ suchen.","gaps":[["Aufträgen"]],"solution":"Selbstständig als Reinigungshilfe arbeiten: Auf Putzfee.net können Sie Ihren Service anbieten und nach **Aufträgen** suchen.","en":"Lavorare in proprio come addetto/a alle pulizie: su Putzfee.net può offrire il Suo servizio e cercare incarichi.","why":"*der Auftrag, die Aufträge* = ordine, incarico; *nach* + dativo plurale aggiunge *-n*: *Aufträgen*.","source":"hueber"},{"label":"C1","lead":"F _ _ _ b _ _ _ _ g","text":"Machen Sie eine ___. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","gaps":[["Fortbildung"]],"solution":"Machen Sie eine **Fortbildung**. Wir bieten interessante Seminare in den Bereichen Technik und Handel.","en":"Faccia un corso di aggiornamento. Offriamo seminari interessanti nei settori tecnica e commercio.","why":"*eine Fortbildung machen* = fare un corso di aggiornamento.","source":"hueber"},{"label":"C2","lead":"K _ _ k _ _ _ e _ z","text":"Denn die ___ schläft nicht!","gaps":[["Konkurrenz"]],"solution":"Denn die **Konkurrenz** schläft nicht!","en":"Perché la concorrenza non dorme!","why":"*die Konkurrenz* = la concorrenza (i rivali).","source":"hueber"},{"label":"D","lead":"v _ _ tr _ _ _ n","text":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter ___ können.","gaps":[["vertreten"]],"solution":"Flexibel und motiviert? Wir suchen Personen, die auf Stundenbasis unsere Lagermitarbeiter **vertreten** können.","en":"Flessibile e motivato/a? Cerchiamo persone che possano sostituire a ore i nostri magazzinieri.","why":"Verbo modale *können* + infinito *vertreten* (senza *zu*).","source":"hueber"}]}]},{"page":"AB 148","heading":"Test Lektion 5","heading_en":"Test della lezione 5","exercises":[{"no":"1","instruction":"Ergänzen Sie.","instruction_en":"Completa le frasi. Il libro dà alcune lettere di ogni parola; scrivi la parola intera.","example":[{"label":"d","text":"Frau Angst will bald **aufhören** zu arbeiten und in Pension gehen."}],"items":[{"label":"a","lead":"A _ _ t _ ä _ e","text":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele ___.","gaps":[["Aufträge"]],"solution":"Die Firma *Müller & Müller* ist sehr gut und hat deshalb viele **Aufträge**.","en":"La ditta Müller & Müller è molto valida e per questo ha molti ordini.","why":"*der Auftrag, die Aufträge* = ordine, ordini; *viele* richiede il plurale."},{"label":"b","lead":"V _ r _ n _ w _ _ t _ _ g","text":"Frau Brügger hat die ___ für 200 Mitarbeiter.","gaps":[["Verantwortung"]],"solution":"Frau Brügger hat die **Verantwortung** für 200 Mitarbeiter.","en":"La signora Brügger ha la responsabilità di 200 collaboratori.","why":"*die Verantwortung für* + accusativo = responsabilità di."},{"label":"c","lead":"_ t _ _ _ _ … h _ _","text":"Die Firma ___ die Möbel aus Schweizer Holz ___.","gaps":[["stellt"],["her"]],"solution":"Die Firma **stellt** die Möbel aus Schweizer Holz **her**.","en":"La ditta produce i mobili con legno svizzero.","why":"*herstellen* = produrre, fabbricare; separabile: *stellt … her*."},{"label":"e","lead":"S _ _ v _ _ _ a _ g _ _ _ _ _ _ _ _ r","text":"Mario ist als ___ in einem Restaurant tätig.","gaps":[["Serviceangestellter"]],"solution":"Mario ist als **Serviceangestellter** in einem Restaurant tätig.","en":"Mario lavora come cameriere in un ristorante.","why":"*der Serviceangestellte* = cameriere (uso svizzero); dopo *als* senza articolo la desinenza è *-er*: *als Serviceangestellter*."},{"label":"f","lead":"z _ st _ _ _ _ g","text":"Peter ist ___ für die Kontrolle und Reparatur der Werkzeugmaschinen.","gaps":[["zuständig"]],"solution":"Peter ist **zuständig** für die Kontrolle und Reparatur der Werkzeugmaschinen.","en":"Peter è responsabile del controllo e della riparazione delle macchine utensili.","why":"*zuständig sein für* = essere responsabile di."},{"label":"g","lead":"F _ _ _ b _ _ d _ _ g _ n","text":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele ___ an.","gaps":[["Fortbildungen"]],"solution":"Die Firma *Müller & Müller* bietet ihren Mitarbeitern viele **Fortbildungen** an.","en":"La ditta Müller & Müller offre ai suoi collaboratori molti corsi di aggiornamento.","why":"*die Fortbildung, die Fortbildungen*; *viele* richiede il plurale."}]},{"no":"2","instruction":"Schreiben Sie die Sätze neu.","instruction_en":"Riscrivi ogni frase con l'inizio dato, usando *zu* + infinito. Scrivi solo la parte dopo la virgola.","example":[{"label":"a","lead":"Fortbildungen interessieren mich nicht!","text":"Ich habe kein Interesse, **Fortbildungen zu machen**."}],"items":[{"label":"b","lead":"Die Zusammenarbeit mit meinen Kollegen macht mir Freude.","text":"Es macht mir Freude, ___.","gaps":[["mit meinen Kollegen zusammenzuarbeiten"]],"solution":"Es macht mir Freude, **mit meinen Kollegen zusammenzuarbeiten**.","en":"Mi piace lavorare insieme ai miei colleghi.","why":"*die Zusammenarbeit* → il verbo *zusammenarbeiten*, separabile: *zusammen**zu**arbeiten*.","source":"g4069"},{"label":"c","lead":"Ich könnte mir eine Arbeit als Pflegefachmann gut vorstellen.","text":"Ich könnte mir gut vorstellen, ___.","gaps":[["als Pflegefachmann zu arbeiten"]],"solution":"Ich könnte mir gut vorstellen, **als Pflegefachmann zu arbeiten**.","en":"Potrei benissimo immaginare di lavorare come infermiere.","why":"*eine Arbeit als …* → *als … zu arbeiten*.","source":"g6865"},{"label":"d","lead":"Der Berufsberater verspricht Hilfe bei der Berufswahl.","text":"Der Berufsberater verspricht, ___.","gaps":[["bei der Berufswahl zu helfen","mir bei der Berufswahl zu helfen","uns bei der Berufswahl zu helfen","bei der Berufswahl zu unterstützen"]],"solution":"Der Berufsberater verspricht, **bei der Berufswahl zu helfen**.","en":"Il consulente di orientamento professionale promette di aiutare nella scelta della professione.","why":"*die Hilfe* → il verbo *helfen*: *zu helfen* alla fine.","source":"g6865"}]},{"no":"3","instruction":"Ergänzen Sie: *während – innerhalb – ausserhalb* und *der – ein – …* in der richtigen Form.","instruction_en":"Completa con *während*, *innerhalb* o *ausserhalb* più l'articolo nella forma giusta (genitivo). Il libro dà la prima lettera dell'articolo.","example":[{"label":"a","text":"Sehr geehrter Herr Safak, vielen Dank für Ihre Bewerbung. Wir melden uns **innerhalb der** nächsten Tage bei Ihnen."}],"items":[{"label":"b1","lead":"Sehr geehrter Herr Safak, wir laden Sie zu einem Vorstellungsgespräch am 2.8. um 10 Uhr ein.","text":"___ Gesprächs können Sie natürlich gern Fragen stellen.","gaps":[["Während des"]],"solution":"**Während des** Gesprächs können Sie natürlich gern Fragen stellen.","en":"Durante il colloquio può naturalmente fare domande.","why":"*während* + genitivo neutro: *des Gesprächs*.","source":"g299310"},{"label":"b2","text":"Bitte geben Sie ___ Woche Bescheid, ob Sie kommen.","gaps":[["innerhalb einer"]],"solution":"Bitte geben Sie **innerhalb einer** Woche Bescheid, ob Sie kommen.","en":"Ci faccia sapere entro una settimana se viene.","why":"*innerhalb* + genitivo femminile: *einer Woche*.","source":"prep"},{"label":"b3","text":"Sie erreichen mich per Telefon oder ___ Bürozeiten per E-Mail.","gaps":[["ausserhalb der"]],"solution":"Sie erreichen mich per Telefon oder **ausserhalb der** Bürozeiten per E-Mail.","en":"Può raggiungermi per telefono oppure, fuori dagli orari d'ufficio, per e-mail.","why":"*ausserhalb* + genitivo plurale: *der Bürozeiten*.","source":"prep"}]},{"no":"4","instruction":"Verbinden Sie.","instruction_en":"Abbina ogni domanda alla risposta giusta (1–5). Scrivi il numero.","phrases":["1 Nein, das kann ich mir nicht vorstellen.","2 Nein, das finde ich nicht.","3 Ja, ich muss eine Kollegin vertreten.","4 Ich beende gerade meine Lehre als Maler.","5 Danke, recht gut. Wir haben viel Arbeit."],"example":[{"label":"a","text":"Wie läuft's denn so in der Firma? → **5** Danke, recht gut. Wir haben viel Arbeit."}],"items":[{"label":"b","text":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → ___","gaps":[["1"]],"solution":"Hast du noch nie daran gedacht, die Stelle zu wechseln? → **1**","en":"Non hai mai pensato di cambiare lavoro? → 1 No, non riesco a immaginarlo.","why":"Una domanda su un'idea: *Nein, das kann ich mir nicht vorstellen.*"},{"label":"c","text":"Was machst du jetzt eigentlich genau? → ___","gaps":[["4"]],"solution":"Was machst du jetzt eigentlich genau? → **4**","en":"Che cosa fai esattamente adesso? → 4 Sto finendo l'apprendistato da imbianchino.","why":"Una domanda con parola interrogativa sul tuo lavoro richiede un fatto come risposta."},{"label":"d","text":"Ist es nicht stressig, nachts zu arbeiten? → ___","gaps":[["2"]],"solution":"Ist es nicht stressig, nachts zu arbeiten? → **2**","en":"Non è stressante lavorare di notte? → 2 No, non credo.","why":"*Ist es nicht stressig …?* chiede un'opinione: *Nein, das finde ich nicht.*"},{"label":"e","text":"Hast du immer noch so viel Arbeit? → ___","gaps":[["3"]],"solution":"Hast du immer noch so viel Arbeit? → **3**","en":"Hai ancora così tanto lavoro? → 3 Sì, devo sostituire una collega.","why":"Domanda sì/no; il motivo del tanto lavoro: *eine Kollegin vertreten*."}]}]},{"page":"AB 149","heading":"Fokus Beruf: Etwas verhandeln","heading_en":"Focus lavoro: negoziare","exercises":[{"no":"1","instruction":"Vier gute Tipps","instruction_en":"Quattro buoni consigli","part":"a","part_instruction":"Wofür bekommt man hier Tipps? Überfliegen Sie den Text und kreuzen Sie an.","part_instruction_en":"A che cosa servono questi consigli? Leggi il testo velocemente e scrivi la risposta giusta. (Gli esercizi 2 e 3 di questa pagina sono ascolti e sono omessi.)","reading":[{"label":"So kommen Sie weiter!","text":"Ist das Bewerbungsgespräch gut gelaufen? Herzlichen Glückwunsch! Jetzt haben Sie es fast geschafft. Aber wenn es im Bewerbungsgespräch zum Thema Geld kommt, machen viele Bewerber Fehler: Sie fordern zu viel Lohn – oder zu wenig. Unsere Tipps helfen Ihnen bei diesem schwierigen Thema.\n1  Sprechen Sie das Thema Geld nicht selbst an. Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.\n2  Nennen Sie Ihre Gehaltsvorstellung. Wenn Sie vorher in anderen Unternehmen gearbeitet haben, ist Ihr letztes Gehalt die Grundlage.\n3  Natürlich können Sie an einem neuen Arbeitsplatz mehr Lohn verlangen, aber bleiben Sie realistisch und begründen Sie Ihre Gehaltsvorstellung: Haben Sie mehr Verantwortung? Können Sie mit besonderen Kenntnissen, Fähigkeiten oder Erfahrungen punkten? War der alte Arbeitgeber besonders zufrieden mit Ihnen?\n4  Was ist, wenn die Personalchefin oder der Personalchef negativ auf Ihre Gehaltsvorstellung reagiert? Dann müssen Sie flexibel sein und andere Vorschläge machen. Erklären Sie zum Beispiel, dass Sie mit weniger Lohn einverstanden sind, wenn die Firma Ihnen eine Weiter- oder Fortbildung bezahlt. Oder wenn Sie nach sechs Monaten mehr Lohn bekommen."}],"items":[{"label":"1","lead":"○ Für Gespräche mit der Bank   ○ Für Gespräche mit dem Arbeitgeber","text":"___","gaps":[["Für Gespräche mit dem Arbeitgeber","mit dem Arbeitgeber","Arbeitgeber","dem Arbeitgeber"]],"solution":"**Für Gespräche mit dem Arbeitgeber**","en":"Per i colloqui con il datore di lavoro","why":"I consigli riguardano come parlare di soldi nel colloquio di lavoro, con la o il responsabile del personale.","source":"hueber"}]},{"no":"1","part":"b","part_instruction":"Was ist richtig? Lesen Sie noch einmal und kreuzen Sie an.","part_instruction_en":"Che cosa è giusto? Rileggi. Scrivi *richtig* (giusto) o *falsch* (sbagliato) dopo ogni frase; nel libro segni solo quelle giuste.","items":[{"label":"1","text":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → ___","gaps":[["richtig","r","ja"]],"solution":"Es ist Aufgabe der Personalchefin / des Personalchefs, das Thema Lohn anzusprechen. → **richtig**","en":"È compito della o del responsabile del personale affrontare il tema dello stipendio. → giusto","why":"Consiglio 1: *Den ersten Schritt sollte die Personalchefin oder der Personalchef machen.*","source":"hueber"},{"label":"2","text":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → ___","gaps":[["falsch","f","nein"]],"solution":"Am neuen Arbeitsplatz bekommen Sie zunächst den gleichen Lohn wie in der alten Firma. → **falsch**","en":"Nel nuovo posto di lavoro all'inizio riceve lo stesso stipendio che nella vecchia ditta. → sbagliato","why":"Consigli 2 e 3: il tuo ultimo stipendio è solo la base; puoi chiedere di più.","source":"hueber"},{"label":"3","text":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → ___","gaps":[["richtig","r","ja"]],"solution":"Wenn Sie mehr Lohn haben möchten, sollten Sie gute Argumente dafür nennen. → **richtig**","en":"Se vuole uno stipendio più alto, dovrebbe dare buoni argomenti. → giusto","why":"Consiglio 3: *begründen Sie Ihre Gehaltsvorstellung*.","source":"hueber"},{"label":"4","text":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → ___","gaps":[["falsch","f","nein"]],"solution":"Wenn die Personalchefin / der Personalchef mit Ihrem Vorschlag nicht einverstanden ist, können Sie nichts weiter machen. → **falsch**","en":"Se la o il responsabile del personale non è d'accordo con la Sua proposta, non può fare più niente. → sbagliato","why":"Consiglio 4: sii flessibile e fai altre proposte (formazione pagata, più stipendio dopo sei mesi).","source":"hueber"}]}]}]}];
